const specialTypes = ['信用风险', '流动性风险', '市场风险', '操作风险', '集中度风险'];
const eventTypes = ['重大操作风险事件', '关注/异常项目事件', '重大合规风险事件', '重大声誉风险事件', '重大信息科技风险事件'];
