const today = () => new Date().toISOString().slice(0, 10);

function useAppState() {
  const [state, setState] = useState<DemoState>(() => loadState());
  const update = (fn: (value: DemoState) => void) => setState(prev => { const next = structuredClone(prev); fn(next); saveState(next); return next; });
  return { state, update, reset: () => setState(resetState()) };
}

function useRouter() {
  const defaultRole = normalizeRole(localStorage.getItem('demo-role'));
  const initialPath = window.location.pathname === '/' ? (defaultRole === '集团管理层' ? '/dashboard' : '/workbench') : (window.location.pathname || '/workbench');
  const [path, setPath] = useState(initialPath);
  const navigate = (next: string) => { window.history.pushState({}, '', next); setPath(next); window.scrollTo(0, 0); };
  useEffect(() => { const fn = () => setPath(window.location.pathname); window.addEventListener('popstate', fn); return () => window.removeEventListener('popstate', fn); }, []);
  return { path, navigate };
}

function Icon({ children }: { children: ReactNode }) { return <span className="menu-icon">{children}</span>; }
function Button({ children, onClick, variant = 'primary', disabled = false, title }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'text' | 'danger'; disabled?: boolean; title?: string }) { const [fallbackOpen, setFallbackOpen] = useState(false); const handler = onClick || (() => setFallbackOpen(true)); return <>{<button title={title || (!onClick ? '点击打开功能弹窗' : undefined)} disabled={disabled} className={`btn btn-${variant}`} onClick={handler}>{children}</button>}{fallbackOpen && <Modal title="功能入口" onClose={() => setFallbackOpen(false)} footer={<Button variant="secondary" onClick={() => setFallbackOpen(false)}>关闭</Button>}><div className="modal-note">该功能入口已打开，可在此继续完成操作。</div></Modal>}</>; }
function StatusTag({ value }: { value: string }) { const cls = /红灯|驳回|停用|已失效|已解除|归档/.test(value) ? 'red' : /黄灯|待审核|待反馈|评估中|草稿|待提交|暂停/.test(value) ? 'orange' : /绿灯|生效|已生效|已反馈|处理中|已报送|部分解除|提交/.test(value) ? 'green' : 'gray'; return <span className={`status ${cls}`}>{value}</span>; }
function SearchPanel({ children, onSearch, onReset }: { children: ReactNode; onSearch: () => void; onReset: () => void }) { return <div className="search-panel"><div className="search-fields">{children}</div><div className="search-actions"><Button onClick={onSearch}>⌕ 检索</Button><Button variant="secondary" onClick={onReset}>重置</Button></div></div>; }
function Field({ label, children, required = false, span = 1 }: { label: string; children: ReactNode; required?: boolean; span?: number }) { return <label className={`field span-${span}`}><span>{label}{required && <b className="required">*</b>}</span>{children}</label>; }
function Input({ value, onChange, placeholder, type = 'text', disabled = false }: { value?: string | number; onChange?: (value: string) => void; placeholder?: string; type?: string; disabled?: boolean }) { return <input disabled={disabled} type={type} value={value ?? ''} placeholder={placeholder} onChange={e => onChange?.(e.target.value)} />; }
function Select({ value, onChange, options, disabled = false }: { value?: string; onChange?: (value: string) => void; options: string[]; disabled?: boolean }) { const lightOptions = options.map(x => x === '不亮灯' ? '绿灯（不预警）' : x); const selected = value === '不亮灯' ? '绿灯（不预警）' : value; return <select disabled={disabled} value={selected ?? ''} onChange={e => onChange?.(e.target.value)}><option value="">请选择</option>{lightOptions.map(x => <option key={x}>{x}</option>)}</select>; }
function Textarea({ value, onChange, placeholder, maxLength, showCount = false }: { value?: string; onChange?: (value: string) => void; placeholder?: string; maxLength?: number; showCount?: boolean }) { const text = value ?? ''; const control = <textarea value={text} placeholder={placeholder} maxLength={maxLength} onChange={e => onChange?.(e.target.value)} />; return showCount ? <div className="textarea-counted">{control}<small>{String(text).length}{maxLength ? ` / ${maxLength}` : ''}</small></div> : control; }
function Section({ title, children, extra }: { title: string; children: ReactNode; extra?: ReactNode }) { return <section className="card section"><div className="section-title"><span>{title}</span>{extra}</div>{children}</section>; }
function Tabs({ items, active, onChange }: { items: string[]; active: string; onChange: (item: string) => void }) { return <div className="tabs">{items.map(item => <button className={active === item ? 'active' : ''} onClick={() => onChange(item)} key={item}>{item}</button>)}</div>; }
function Pagination({ total, pageSize = 10, page, setPage }: { total: number; pageSize?: number; page: number; setPage: (value: number) => void }) { const pages = Math.max(1, Math.ceil(total / pageSize)); return <div className="pagination"><span>共 {total} 条</span><select value={pageSize} onChange={() => undefined}><option>10 条/页</option></select><button disabled={page <= 1} onClick={() => setPage(Math.max(1, page - 1))}>‹</button>{Array.from({ length: Math.min(pages, 4) }, (_, i) => i + 1).map(p => <button key={p} className={page === p ? 'current' : ''} onClick={() => setPage(p)}>{p}</button>)}<button disabled={page >= pages} onClick={() => setPage(Math.min(pages, page + 1))}>›</button><span>前往</span><input value={page} onChange={e => setPage(Math.min(pages, Math.max(1, Number(e.target.value) || 1)))} /></div>; }
function WorkflowSteps({ steps, current, rejected = false }: { steps: string[]; current: number; rejected?: boolean }) { return <div className="workflow">{steps.map((step, index) => <div key={step} className={`workflow-step ${index < current ? 'done' : index === current ? (rejected ? 'rejected' : 'current') : ''}`}><div className="workflow-dot">{index < current ? '✓' : index + 1}</div><span>{index + 1}. {step}</span></div>)}</div>; }
function OperationHistory({ logs }: { logs: { id: string; action: string; operator: string; time: string; content: string }[] }) { return <div className="timeline">{logs.map(log => <div className="timeline-item" key={log.id}><i /><div><b>{log.action}</b><span>{log.operator} · {log.time}</span><p>{log.content}</p></div></div>)}</div>; }
function FileUploader({ files, onChange, multiple = true }: { files: Attachment[]; onChange: (files: Attachment[]) => void; multiple?: boolean }) { const onFiles = (e: ChangeEvent<HTMLInputElement>) => { const list = Array.from(e.target.files || []).map(makeAttachment); onChange(multiple ? [...files, ...list] : list.slice(0, 1)); e.target.value = ''; }; const remove = (id: string) => onChange(files.filter(x => x.id !== id)); return <div className="file-uploader"><label className="upload-drop"><input type="file" multiple={multiple} onChange={onFiles} /><span className="upload-icon">⇧</span><b>点击上传或拖拽文件至此</b><small>支持 PDF、Word、Excel、图片等格式</small></label>{files.length > 0 && <div className="file-list">{files.map(file => <div className="file-row" key={file.id}><span>▣ {file.name}</span><small>{formatSize(file.size)} · {file.uploadedAt}</small><div><Button variant="text" onClick={() => downloadText(file.name + '.txt', `文件：${file.name}\n类型：${file.type}\n大小：${formatSize(file.size)}`)}>下载</Button><Button variant="text" onClick={() => remove(file.id)}>删除</Button></div></div>)}</div>}</div>; }
function EmptyModulePage({ title }: { title: string }) { return <Page title={title} breadcrumb={['其他模块', title]}><div className="empty-state"><div className="empty-icon">▧</div><h2>该模块详细设计见其他需求说明</h2><p>需求书 4.7–4.11 未提供字段及操作规则，当前保留统一菜单入口。</p></div></Page>; }
const isModalRoute = (path: string) => { const listRoutes = ['/warning/risk-preference', '/warning/rules', '/warning/disposal', '/indicators/maintenance', '/indicators/versions', '/major-events', '/reports', '/periodic-reports', '/special-risks/drafts', '/special-risks/manage', '/special-risks/feedback']; return path !== '/dashboard' && path !== '/workbench' && !listRoutes.includes(path) && (path.endsWith('/new') || path.endsWith('/edit') || path.includes('/config') || path.includes('/approve') || path.includes('/submissions') || !!path.match(/^\/(warning|indicators|major-events|reports|periodic-reports|special-risks)\/[^/]+/)); };
function Page({ title, breadcrumb, children, actions, onClose, inline = false, hidePageTitle = false }: { title: string; breadcrumb: string[]; children: ReactNode; actions?: ReactNode; onClose?: () => void; inline?: boolean; hidePageTitle?: boolean }) { const content = <><div className="breadcrumb">集团并表管理系统 <span>›</span> {breadcrumb.join(' › ')}</div>{!hidePageTitle && <div className="page-title"><h1>{title}</h1><div>{actions}</div></div>}{children}</>; if (inline || !isModalRoute(window.location.pathname)) return content; return <div className="modal-mask route-modal-mask"><div className="modal route-modal"><div className="route-modal-caption"><b>{title}</b><button aria-label="关闭" title="关闭" onClick={onClose || (() => window.history.back())}>×</button></div><div className="route-modal-body">{content}</div></div></div>; }
function Table({ children }: { children: ReactNode }) { return <div className="table-wrap"><table>{children}</table></div>; }
function Modal({ title, children, onClose, footer }: { title: string; children: ReactNode; onClose: () => void; footer?: ReactNode }) { return <div className="modal-mask"><div className="modal"><div className="modal-title"><b>{title}</b><button onClick={onClose}>×</button></div><div className="modal-body">{children}</div>{footer && <div className="modal-footer">{footer}</div>}</div></div>; }

function Header({ role, setRole, onReset }: { role: Role; setRole: (role: Role) => void; onReset: () => void }) { return <header className="app-header"><div className="brand"><span className="brand-mark">▥</span><b>集团并表管理系统</b></div><div className="header-date">▣ 2024-06-30　13:22:45　 星期日</div><div className="header-right"><span className="bell">♧<i>12</i></span><span>?</span><span className="divider" /><span>{role === '各金融机构' ? currentInstitution : '集团并表范围'}⌄</span><label className="role-switch"><span>当前演示角色</span><select value={role} onChange={e => setRole(e.target.value as Role)}>{roleLabels.map(x => <option key={x}>{x}</option>)}</select></label><button className="reset-demo" onClick={onReset}>恢复演示数据</button><span className="avatar">张</span><span>张三⌄</span></div></header>; }

type MenuItem = { label: string; path?: string; icon: string; children?: { label: string; path: string }[] };
const menus: MenuItem[] = [
  { label: '并表驾驶舱', icon: '▦', path: '/dashboard' },
  { label: '工作台', icon: '⌂', path: '/workbench' },
  { label: '预警管理', icon: '★', children: [{ label: '风险偏好及目标', path: '/warning/risk-preference' }, { label: '风险预警规则管理', path: '/warning/rules' }, { label: '预警提示与处置', path: '/warning/disposal' }] },
  { label: '指标管理', icon: '▤', children: [{ label: '指标新增与维护', path: '/indicators/maintenance' }, { label: '指标版本管理', path: '/indicators/versions' }] },
  { label: '重大风险事件管理', icon: '▧', path: '/major-events' },
  { label: '报表中心', icon: '▨', path: '/reports' },
  { label: '定期报告', icon: '▤', path: '/periodic-reports' },
  { label: '专项风险管理', icon: '⚑', children: [{ label: '新建专项风险提示', path: '/special-risks/drafts' }, { label: '专项风险提示与管理', path: '/special-risks/manage' }, { label: '专项风险查看与反馈', path: '/special-risks/feedback' }] },
  { label: '资本规划与预算', icon: '◫', path: '/empty/capital' },
  { label: '会计并表管理', icon: '▧', path: '/empty/accounting' },
  { label: '关联交易管理', icon: '♧', path: '/empty/related' },
  { label: '知识库管理', icon: '▣', path: '/empty/knowledge' },
  { label: '系统管理', icon: '⚙', path: '/empty/system' },
];
function Sidebar({ path, navigate }: { path: string; navigate: (path: string) => void }) { const [open, setOpen] = useState<string[]>(['预警管理', '指标管理', '专项风险管理']); return <aside className="sidebar">{menus.map(menu => { const active = menu.path === path || menu.children?.some(x => path.startsWith(x.path)); const expanded = open.includes(menu.label); return <div key={menu.label}><button className={`menu-root ${active ? 'active-root' : ''}`} onClick={() => menu.children ? setOpen(value => value.includes(menu.label) ? value.filter(x => x !== menu.label) : [...value, menu.label]) : menu.path && navigate(menu.path)}><Icon>{menu.icon}</Icon><span>{menu.label}</span>{menu.children && <em>{expanded ? '⌃' : '⌄'}</em>}</button>{menu.children && expanded && <div className="menu-children">{menu.children.map(child => <button className={path === child.path || path.startsWith(child.path + '/') ? 'active-child' : ''} key={child.path} onClick={() => navigate(child.path)}>{child.label}</button>)}</div>}</div>; })}</aside>; }

function App() {
  const { path, navigate } = useRouter();
  const { state: completeState, update, reset } = useAppState();
  const [role, setRole] = useState<Role>(() => normalizeRole(localStorage.getItem('demo-role')));
  const state = scopeStateForRole(completeState, role);
  const [notice, setNotice] = useState<string | null>(null);
  useEffect(() => localStorage.setItem('demo-role', role), [role]);
  const operator = role;
  const toast = (message: string) => setNotice(message);
  const changeRole = (nextRole: Role) => {
    setRole(nextRole);
    if (path.startsWith('/major-events/new') && !can(nextRole, 'event-create')) return navigate('/major-events');
    if (path === '/dashboard' || path === '/workbench' || path === '/') navigate(nextRole === '集团管理层' ? '/dashboard' : '/workbench');
  };
  const goBack = () => navigate('/warning/risk-preference');
  const render = () => {
    if (path === '/dashboard') return <Dashboard state={state} navigate={navigate} />;
    if (path === '/workbench') return <Workbench state={state} role={role} navigate={navigate} />;
    if (path.includes('/empty/')) return <EmptyModulePage title={menus.flatMap(x => [x, ...(x.children || [])]).find((x: any) => x.path === path)?.label || '模块占位页'} />;
    if (path === '/warning/risk-preference') return <RiskPreferenceList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.endsWith('/new') && path.startsWith('/warning/risk-preference')) return <RiskPreferenceEditor state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/warning/risk-preference/')) return <RiskPreferenceDetail state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/warning/rules') return <WarningRules state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.match(/^\/warning\/rules\/[^/]+\/approve$/)) return <RuleApprove state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/warning/rules/')) return <RuleConfig state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/warning/disposal') return <WarningDisposalList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/warning/disposal/')) return <WarningDisposalDetail state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/indicators/maintenance') return <IndicatorList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/indicators/versions') return <IndicatorVersions state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/indicators/maintenance/')) return <IndicatorEditor state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/major-events') return <MajorEventList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/major-events/new' || path.match(/^\/major-events\/[^/]+\/edit$/)) return <MajorEventEditor state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.endsWith('/follow-up')) return <EventFollowUp state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.endsWith('/final-report')) return <EventFinalReport state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/major-events/')) return <MajorEventDetail state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/reports') return <Reports state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/reports/upload') return <ReportUpload state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.endsWith('/submissions')) return <ReportSubmissions state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/periodic-reports') return <PeriodicReports state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/periodic-reports/upload' || path.endsWith('/edit')) return <PeriodicReportEditor state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/special-risks/drafts') return <SpecialRiskDrafts state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/special-risks/new') return <SpecialRiskEditor state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/special-risks/manage') return <SpecialRiskManage state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/special-risks/manage/')) return <SpecialRiskView state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path === '/special-risks/feedback') return <SpecialRiskFeedbackList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.endsWith('/evaluate')) return <SpecialRiskEvaluate state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    if (path.startsWith('/special-risks/feedback/')) return <SpecialRiskFeedback state={state} role={role} navigate={navigate} update={update} toast={toast} />;
    return <RiskPreferenceList state={state} role={role} navigate={navigate} update={update} toast={toast} />;
  };
  return <div className="app"><Header role={role} setRole={changeRole} onReset={() => { reset(); toast('演示数据已恢复'); }} /><Sidebar path={path} navigate={navigate} /><main className="content">{render()}</main>{notice && <Modal title="操作提示" onClose={() => setNotice(null)} footer={<Button variant="secondary" onClick={() => setNotice(null)}>关闭</Button>}><div className="modal-note">{notice}</div></Modal>}</div>;
}

type PageProps = { state: DemoState; role: Role; navigate: (path: string) => void; update: (fn: (state: DemoState) => void) => void; toast: (message: string) => void };
const TextAction = ({ children, onClick, disabled = false }: { children: ReactNode; onClick?: () => void; disabled?: boolean }) => <button className="text-action" disabled={disabled} onClick={onClick}>{children}</button>;
const permitted = (role: Role, action: string) => can(role, action);

function Dashboard({ state, navigate }: { state: DemoState; navigate: (path: string) => void }) { const red = state.warningDisposals.filter(x => x.level === '红灯').length; const yellow = state.warningDisposals.filter(x => x.level === '黄灯').length; const green = Math.max(0, state.warningRules.length * 18 - red - yellow); const metrics = [['纳入机构数', '5', '上海农商银行等五家机构'], ['风险偏好指标', String(state.riskPreferences.reduce((n, x) => n + x.indicators.length, 0)), '指标运行中'], ['预警规则总数', String(state.warningRules.length), '规则持续监测'], ['重大风险事件', String(state.majorEvents.length), '当前台账'], ['专项风险事项', String(state.specialRisks.length), '提示及工单'], ['报表报送总数', String(state.reports.reduce((n, x) => n + x.submissions.length, 0)), '历次报送记录']] as const; const capital = [19.16, 18.73, 17.82, 16.25, 22.31]; const riskRows = [['信用风险', 72], ['流动性风险', 48], ['市场风险', 36], ['操作风险', 24], ['集中度风险', 42]] as const; return <Page title="并表管理驾驶舱" breadcrumb={['并表驾驶舱']}><div className="cockpit-banner"><div><span className="cockpit-kicker">GROUP CONSOLIDATED RISK MANAGEMENT</span><h2>并表管理驾驶舱</h2><p>风险、资本、预警、事件与报送运行态势 · 更新时间 2024-06-30 13:22:45</p></div><div className="cockpit-banner-actions"><Button variant="secondary" onClick={() => navigate('/workbench')}>进入工作台</Button><Button onClick={() => navigate('/warning/disposal')}>查看风险事项</Button></div></div><div className="cockpit-kpis">{metrics.map(([label, value, hint]) => <button className="cockpit-kpi" key={label} onClick={() => label === '重大风险事件' ? navigate('/major-events') : label === '专项风险事项' ? navigate('/special-risks/manage') : label === '报表报送总数' ? navigate('/reports') : navigate('/warning/risk-preference')}><span>{label}</span><b>{value}</b><small>{hint}　›</small></button>)}</div><div className="cockpit-main-grid"><Section title="资本充足率"><div className="cockpit-line-head"><div><small>当前水平</small><strong>19.16%</strong><em>较上月 +0.42%</em></div><StatusTag value="运行良好" /></div><div className="cockpit-line-chart"><div className="line-grid"><i /><i /><i /><i /></div><svg viewBox="0 0 640 170" preserveAspectRatio="none"><polyline points="0,124 58,113 116,125 175,92 234,108 292,73 350,92 408,66 466,88 524,44 582,59 640,27" fill="none" stroke="#5aa8ff" strokeWidth="4" /><polygon points="0,124 58,113 116,125 175,92 234,108 292,73 350,92 408,66 466,88 524,44 582,59 640,27 640,170 0,170" fill="rgba(75,145,248,.18)" /></svg><div className="line-months">{['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'].map(x => <span key={x}>{x}</span>)}</div></div></Section><Section title="机构资本充足率对比"><div className="cockpit-bars">{institutions.map((name, i) => <div className="cockpit-bar-row" key={name}><span>{name}</span><div><i style={{ height: String(Math.max(24, capital[i] * 3.3)) + 'px' }} /><b>{capital[i].toFixed(2)}%</b></div></div>)}</div><div className="cockpit-axis"><span>0%</span><span>10%</span><span>20%</span><span>30%</span></div></Section></div><div className="cockpit-three-grid"><Section title="预警灯号概览" extra={<TextAction onClick={() => navigate('/warning/disposal')}>查看全部</TextAction>}><div className="lamp-grid"><button className="lamp-card red" onClick={() => navigate('/warning/disposal')}><i /><b>{red}</b><span>红灯预警</span><small>立即处置</small></button><button className="lamp-card yellow" onClick={() => navigate('/warning/disposal')}><i /><b>{yellow}</b><span>黄灯预警</span><small>持续跟踪</small></button><button className="lamp-card green" onClick={() => navigate('/warning/rules')}><i /><b>{green}</b><span>绿灯</span><small>不预警</small></button></div></Section><Section title="风险类别分布"><div className="risk-bars cockpit-risk-bars">{riskRows.map(([name, value], i) => <div key={name}><span>{name}</span><div><i className={i < 1 ? 'red' : i < 3 ? 'orange' : 'green'} style={{ width: String(value) + '%' }} /></div><b>{value}%</b></div>)}</div><div className="cockpit-risk-note">风险类别按当前监测规则分布</div></Section><Section title="重大风险事件概览" extra={<TextAction onClick={() => navigate('/major-events')}>进入台账</TextAction>}><div className="mini-summary"><button onClick={() => navigate('/major-events')}><b>{state.majorEvents.length}</b><span>事件总数</span></button><button onClick={() => navigate('/major-events')}><b>{state.majorEvents.filter(x => x.status === '处理中').length}</b><span>处理中</span></button><button onClick={() => navigate('/major-events')}><b>{state.majorEvents.filter(x => x.latestReport === '续报').length}</b><span>续报跟踪</span></button><button onClick={() => navigate('/major-events')}><b>{state.majorEvents.filter(x => x.status === '已归档').length}</b><span>已归档</span></button></div></Section></div><div className="cockpit-two-grid"><Section title="专项风险提示概览" extra={<TextAction onClick={() => navigate('/special-risks/manage')}>查看详情</TextAction>}><div className="summary-strip"><button onClick={() => navigate('/special-risks/manage')}><b>{state.specialRisks.length}</b><span>提示总数</span></button><button onClick={() => navigate('/special-risks/feedback')}><b>{state.specialRisks.flatMap(x => x.workOrders).filter(x => x.status === '待反馈').length}</b><span>待反馈</span></button><button onClick={() => navigate('/special-risks/feedback')}><b>{state.specialRisks.flatMap(x => x.workOrders).filter(x => x.status === '评估中').length}</b><span>评估中</span></button><button onClick={() => navigate('/special-risks/manage')}><b>{state.specialRisks.flatMap(x => x.workOrders).filter(x => x.status === '已解除').length}</b><span>已解除</span></button></div></Section><Section title="报表报送概览" extra={<TextAction onClick={() => navigate('/reports')}>查看报表</TextAction>}><div className="summary-strip"><button onClick={() => navigate('/reports')}><b>{state.reports.length}</b><span>报表项目</span></button><button onClick={() => navigate('/reports')}><b>{state.reports.reduce((n, x) => n + x.submissions.length, 0)}</b><span>报送次数</span></button><button onClick={() => navigate('/periodic-reports')}><b>{state.periodicReports.length}</b><span>定期报告</span></button><button onClick={() => navigate('/reports/upload')}><b>＋</b><span>上传报表</span></button></div></Section></div><Section title="关键指标监测" extra={<TextAction onClick={() => navigate('/indicators/maintenance')}>进入指标管理</TextAction>}><div className="key-metrics">{[['资本充足率', '19.16%', '+0.42%', 'green'], ['存款集中度', '72.7%', '-2.1%', 'green'], ['净稳定资金率', '92.4%', '+3.2%', 'orange'], ['合格资本充足率', '121.5%', '+1.8%', 'green'], ['不良资产率', '1.14%', '-0.23%', 'green']].map(x => <button className="key-metric" key={x[0]} onClick={() => navigate('/indicators/maintenance')}><span>{x[0]}</span><b>{x[1]}</b><em className={x[3]}>{x[2]}</em><div className="metric-spark"><i /><i /><i /><i /><i /></div></button>)}</div></Section></Page>; }

function Workbench({ state, role, navigate }: { state: DemoState; role: Role; navigate: (path: string) => void }) { const [todoTab, setTodoTab] = useState('全部'); const [selected, setSelected] = useState<string[]>([]); const [notice, setNotice] = useState<string | null>(null); const todos = [{ id: 'todo-1', tag: '红灯', category: '预警处置', title: '国际AMC不良资产率预警处置', institution: '国际AMC', deadline: '今日 17:00', desc: '填写当前处置节点并提交应对方案', path: '/warning/disposal/wd-1' }, { id: 'todo-2', tag: '待审阅', category: '流程审阅', title: '浦发银行净稳定资金率规则', institution: '浦发银行', deadline: '今日 18:00', desc: '规则配置提交管理层审阅', path: '/warning/rules/wr-3/approve' }, { id: 'todo-3', tag: '待反馈', category: '预警处置', title: '重点行业信用风险专项提示反馈', institution: '国泰海通', deadline: '明日 12:00', desc: '补充机构自检与风险反馈', path: '/special-risks/feedback' }, { id: 'todo-4', tag: '待确认', category: '报表确认', title: '集团并表风险监测月报报送确认', institution: '上海农商银行', deadline: '明日 16:00', desc: '确认最新报表文件及报送说明', path: '/reports' }, { id: 'todo-5', tag: '处理中', category: '重大事件', title: '重大风险事件续报跟踪', institution: '中国太平洋保险', deadline: '持续跟踪', desc: '查看事件流程与最新进展', path: '/major-events/me-1' }]; const running = [{ name: '风险偏好及目标', type: '指标与偏好', count: state.riskPreferences.length, progress: 82, status: '运行中', path: '/warning/risk-preference' }, { name: '预警规则监测', type: '阈值规则', count: state.warningRules.filter(x => x.status === '生效').length, progress: 76, status: '运行中', path: '/warning/rules' }, { name: '重大风险事件', type: '事件台账', count: state.majorEvents.length, progress: 64, status: '持续跟踪', path: '/major-events' }, { name: '报表报送', type: '报表与报告', count: state.reports.reduce((n, x) => n + x.submissions.length, 0), progress: 91, status: '持续更新', path: '/reports' }, { name: '专项风险工单', type: '机构协同', count: state.specialRisks.flatMap(x => x.workOrders).length, progress: 58, status: '闭环跟踪', path: '/special-risks/feedback' }]; const filtered = todoTab === '全部' ? todos : todos.filter(x => x.category === todoTab); const toggle = (id: string) => setSelected(v => v.includes(id) ? v.filter(x => x !== id) : [...v, id]); const notify = (message: string) => setNotice(message); const taskProgress = [{ name: '预警处置', value: 72, note: '红黄灯事项闭环' }, { name: '流程审阅', value: 64, note: '规则与方案审阅' }, { name: '报表确认', value: 91, note: '最新报送确认' }, { name: '整改跟踪', value: 58, note: '机构反馈与整改' }]; return <Page title="工作台" breadcrumb={['工作台']}><div className="workbench-head"><div><span className="cockpit-kicker">ROLE-BASED WORKSPACE</span><h2>{role}</h2><p>统一接收上报、补正、审核、预警处置、整改和报表确认任务，集中查看进度与消息提醒。</p></div><div className="workbench-head-actions"><Button variant="secondary" onClick={() => notify('已打开工作台消息中心，可按任务、预警和报送类型查看全部提醒。')}>消息中心 <span className="notice-badge">6</span></Button><Button onClick={() => navigate('/dashboard')}>返回驾驶舱</Button></div></div><div className="workbench-kpis"><button onClick={() => setTodoTab('全部')}><span>待办任务</span><b>{todos.length}</b><small>上报 / 审阅 / 处置</small></button><button onClick={() => navigate('/warning/disposal')}><span>预警处置</span><b>{state.warningDisposals.length}</b><small>红灯、黄灯和绿灯跟踪</small></button><button onClick={() => navigate('/indicators/maintenance')}><span>指标与偏好</span><b>{state.indicators.length + state.riskPreferences.length}</b><small>指标及方案运行</small></button><button onClick={() => navigate('/major-events')}><span>重大风险事件</span><b>{state.majorEvents.length}</b><small>流程节点跟踪</small></button><button onClick={() => navigate('/reports')}><span>风险报告与报表</span><b>{state.reports.length + state.periodicReports.length}</b><small>查看最新报送</small></button></div><div className="workbench-main-grid"><Section title="统一待办" extra={<div className="todo-actions"><Button variant="secondary" disabled={!selected.length} onClick={() => notify('已对选中的 ' + selected.length + ' 项任务执行批量处理。')}>批量处理</Button><Button variant="secondary" disabled={!selected.length} onClick={() => notify('已向相关责任机构发送催办提醒。')}>催办</Button><Button variant="secondary" disabled={!selected.length} onClick={() => notify('已打开转办弹窗，可选择责任部门和处理人。')}>转办</Button></div>}><div className="todo-tabs">{['全部', '预警处置', '流程审阅', '报表确认'].map(x => <button className={todoTab === x ? 'active' : ''} onClick={() => setTodoTab(x)} key={x}>{x}</button>)}</div><div className="todo-table-wrap"><table className="workbench-todo-table"><thead><tr><th><input type="checkbox" checked={selected.length === filtered.length && filtered.length > 0} onChange={e => setSelected(e.target.checked ? filtered.map(x => x.id) : [])} /></th><th>任务事项</th><th>所属机构</th><th>截止时间</th><th>状态</th><th>操作</th></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><input type="checkbox" checked={selected.includes(item.id)} onChange={() => toggle(item.id)} /></td><td><b>{item.title}</b><small>{item.desc}</small></td><td>{item.institution}</td><td>{item.deadline}</td><td><StatusTag value={item.tag} /></td><td><TextAction onClick={() => navigate(item.path)}>处理</TextAction></td></tr>)}</tbody></table></div><div className="workbench-todo-foot">已选 {selected.length} 项 · 当前显示 {filtered.length} 项 <TextAction onClick={() => notify('已刷新当前角色的任务、预警和消息提醒。')}>刷新待办</TextAction></div></Section><Section title="消息提醒" extra={<TextAction onClick={() => notify('已标记全部消息为已读。')}>全部已读</TextAction>}><div className="workbench-messages"><button onClick={() => notify('消息：红灯预警事项已进入当前处置节点，请及时提交方案。')}><i className="message-dot red" /><div><b>红灯预警处置提醒</b><span>国际AMC不良资产率超过红灯阈值</span></div><small>10分钟前</small></button><button onClick={() => notify('消息：规则配置已提交管理层审阅，请关注审阅结果。')}><i className="message-dot blue" /><div><b>流程节点提醒</b><span>浦发银行规则配置等待管理层审阅</span></div><small>30分钟前</small></button><button onClick={() => notify('消息：专项风险提示反馈期限临近，请提醒相关机构。')}><i className="message-dot orange" /><div><b>机构反馈提醒</b><span>专项风险提示反馈期限临近</span></div><small>1小时前</small></button><button onClick={() => notify('消息：报表中心已收到最新一批报送文件。')}><i className="message-dot green" /><div><b>报表报送消息</b><span>集团并表风险监测月报已更新</span></div><small>今日</small></button></div><div className="message-footer"><span>提醒方式：站内信 · 邮件 · 集团消息平台</span><TextAction onClick={() => notify('提醒设置已打开，可配置站内信、邮件和集团消息平台。')}>提醒设置</TextAction></div></Section></div><div className="workbench-lower-grid"><Section title="运行清单" extra={<Button variant="secondary" onClick={() => navigate('/warning/risk-preference')}>进入业务管理</Button>}><Table><thead><tr><th>运行对象</th><th>业务类型</th><th>数量</th><th>完成进度</th><th>状态</th><th>入口</th></tr></thead><tbody>{running.map(item => <tr key={item.name}><td>{item.name}</td><td>{item.type}</td><td>{item.count}</td><td><div className="progress-line"><i style={{ width: String(item.progress) + '%' }} /><span>{item.progress}%</span></div></td><td><StatusTag value={item.status} /></td><td><TextAction onClick={() => navigate(item.path)}>查看</TextAction></td></tr>)}</tbody></Table></Section><Section title="任务处理进度" extra={<TextAction onClick={() => setTodoTab('全部')}>查看待办</TextAction>}><div className="task-progress-cards">{taskProgress.map(item => <button key={item.name} onClick={() => setTodoTab(item.name === '预警处置' ? '预警处置' : item.name === '流程审阅' ? '流程审阅' : item.name === '报表确认' ? '报表确认' : '全部')}><div><b>{item.name}</b><span>{item.note}</span></div><div className="progress-line"><i style={{ width: String(item.value) + '%' }} /><span>{item.value}%</span></div></button>)}</div></Section></div><div className="workbench-bottom-grid"><Section title="近期操作"><div className="workbench-history"><div><b>预警规则配置</b><span>刚刚 · 规则配置已提交管理层审阅</span></div><div><b>专项风险提示</b><span>今日 · 已生成五家机构反馈工单</span></div><div><b>重大风险事件</b><span>今日 · 事件流程进入续报跟踪</span></div></div></Section><Section title="快捷入口"><div className="quick-links"><Button variant="secondary" onClick={() => navigate('/warning/rules')}>预警规则管理</Button><Button variant="secondary" onClick={() => navigate('/major-events')}>重大风险事件</Button><Button variant="secondary" onClick={() => navigate('/reports')}>报表中心</Button><Button variant="secondary" onClick={() => navigate('/special-risks/manage')}>专项风险管理</Button></div></Section></div>{notice && <Modal title="工作台操作" onClose={() => setNotice(null)} footer={<Button variant="secondary" onClick={() => setNotice(null)}>关闭</Button>}><div className="modal-note">{notice}</div></Modal>}</Page>; }
function RiskPreferenceList({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ name: '', institution: '', status: '', running: true }); const [page, setPage] = useState(1); const items = state.riskPreferences.filter(x => (!q.name || x.name.includes(q.name)) && (!q.institution || x.institution.includes(q.institution)) && (!q.status || x.status === q.status) && (!q.running || x.status === '已生效')); return <Page title="风险偏好及目标" breadcrumb={['预警管理', '风险偏好及目标']} actions={permitted(role, 'preference-create') && <Button onClick={() => navigate('/warning/risk-preference/new')}>＋ 新增方案</Button>}><SearchPanel onSearch={() => setPage(1)} onReset={() => setQ({ name: '', institution: '', status: '', running: true })}><Field label="方案名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} placeholder="请输入方案名称" /></Field><Field label="覆盖机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field><Field label="方案状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['待提交', '待审核', '已生效', '已失效']} /></Field><Field label="生效起止时间"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="指标名称"><Input placeholder="请输入指标名称" /></Field><label className="check-field"><input type="checkbox" checked={q.running} onChange={e => setQ({ ...q, running: e.target.checked })} /> 仅展示运行中方案</label></SearchPanel><div className="list-toolbar"><span>风险偏好方案列表</span><Button variant="secondary" onClick={() => downloadCSV('风险偏好方案.csv', [['方案编号', '方案名称', '覆盖机构', '状态'], ...items.map(x => [x.code, x.name, x.institution, x.status])])}>⇩ 批量导出</Button></div><Table><thead><tr><th>序号</th><th>方案编号</th><th>方案名称</th><th>覆盖机构范围</th><th>生效时间</th><th>失效时间</th><th>方案状态</th><th>操作</th><th>方案流程</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td className="link">{item.code}</td><td>{item.name}</td><td>{item.institution}</td><td>{item.effectiveDate}</td><td>{item.expiryDate || '—'}</td><td><StatusTag value={item.status} /></td><td><TextAction disabled={!permitted(role, 'preference-edit')} onClick={() => navigate(`/warning/risk-preference/${item.id}/edit`)}>编辑</TextAction><TextAction onClick={() => navigate(`/warning/risk-preference/${item.id}`)}>查看</TextAction></td><td><TextAction onClick={() => toast(`流程：${item.logs.map(x => x.action).join(' → ')}`)}>查看流程</TextAction></td></tr>)}</tbody></Table><Pagination total={items.length} page={page} setPage={setPage} /></Page>; }

function RiskPreferenceEditor({ state, role, navigate, update, toast }: PageProps) { const editingId = window.location.pathname.split('/')[3]; const editing = state.riskPreferences.find(x => x.id === editingId); const [form, setForm] = useState<Partial<RiskPreference>>(() => editing ? structuredClone(editing) : { name: '', institution: '', effectiveDate: '', expiryDate: '', department: '金融机构管理部', summary: '', statement: '', indicators: [], attachments: [] }); const [files, setFiles] = useState<Attachment[]>(form.attachments || []); const indicators = form.indicators || []; const set = (patch: Partial<RiskPreference>) => setForm(x => ({ ...x, ...patch })); const save = (submit: boolean) => { if (!form.name || !form.institution || !form.effectiveDate || !form.expiryDate || !form.statement) return toast('请完整填写方案名称、覆盖机构、生效/失效时间和定性风险偏好陈述'); update(s => { if (editing) { const item = s.riskPreferences.find(x => x.id === editing.id)!; riskPreferenceService.update(item, { ...form, attachments: files, status: submit ? '待审核' : item.status }, submit ? '提交审阅' : '保存草稿', submit ? '方案已提交审阅' : '保存方案草稿', role); } else { const item = riskPreferenceService.create(s, { ...form, attachments: files }, role); if (submit) riskPreferenceService.update(item, { status: '待审核' }, '提交审阅', '方案已提交审阅', role); } }); toast(submit ? '方案已提交审阅' : '草稿已保存'); navigate('/warning/risk-preference'); }; const addIndicator = () => set({ indicators: [...indicators, { id: uid('rpi'), category: '资本充足类', name: '', definition: '', unit: '%', institution: form.institution || '上海农商银行', frequency: '月度', warning: '', tolerance: '', effectiveDate: form.effectiveDate || today() }] }); const updateIndicator = (id: string, patch: Record<string, string>) => set({ indicators: indicators.map(x => x.id === id ? { ...x, ...patch } : x) }); return <Page title={editing ? '风险偏好及目标 - 编辑方案' : '风险偏好及目标 - 新建方案'} breadcrumb={['预警管理', '风险偏好及目标', editing ? '编辑方案' : '新建方案']} actions={<><Button variant="secondary" onClick={() => navigate('/warning/risk-preference')}>返回</Button><Button variant="secondary" onClick={() => save(false)}>保存草稿</Button><Button onClick={() => save(true)} disabled={!permitted(role, 'preference-create')}>提交审阅</Button></>}><Section title="基本信息"><div className="form-grid"><Field label="方案编号"><Input value={editing?.code || '系统自动生成'} disabled /></Field><Field label="方案状态"><StatusTag value={editing?.status || '待提交'} /></Field><Field label="方案名称" required><Input value={form.name} onChange={v => set({ name: v })} /></Field><Field label="覆盖机构范围" required><Select value={form.institution} onChange={v => set({ institution: v })} options={institutions} /></Field><Field label="生效时间" required><Input type="date" value={form.effectiveDate} onChange={v => set({ effectiveDate: v })} /></Field><Field label="失效时间" required><Input type="date" value={form.expiryDate} onChange={v => set({ expiryDate: v })} /></Field><Field label="编制部门"><Select value={form.department} onChange={v => set({ department: v })} options={departments} /></Field><Field label="编制摘要" span={2}><Textarea value={form.summary} onChange={v => set({ summary: v })} /></Field></div></Section><Section title="定性风险偏好陈述"><Field label="定性风险偏好陈述" required><Textarea value={form.statement} onChange={v => set({ statement: v })} /></Field></Section><Section title="风险偏好指标配置" extra={<><Button variant="secondary" onClick={addIndicator}>＋ 新增指标</Button><Button variant="secondary" onClick={() => toast('批量导入模板已打开，可继续选择本地文件')}>批量导入</Button></>}><Table><thead><tr><th>序号</th><th>风险类别</th><th>指标名称</th><th>指标定义</th><th>单位</th><th>适用机构</th><th>控制频率</th><th>预警值</th><th>容忍值</th><th>操作</th></tr></thead><tbody>{indicators.map((x, i) => <tr key={x.id}><td>{i + 1}</td><td><Select value={x.category} onChange={v => updateIndicator(x.id, { category: v })} options={riskTypes} /></td><td><Input value={x.name} onChange={v => updateIndicator(x.id, { name: v })} /></td><td><Input value={x.definition} onChange={v => updateIndicator(x.id, { definition: v })} /></td><td><Input value={x.unit} onChange={v => updateIndicator(x.id, { unit: v })} /></td><td><Select value={x.institution} onChange={v => updateIndicator(x.id, { institution: v })} options={institutions} /></td><td><Select value={x.frequency} onChange={v => updateIndicator(x.id, { frequency: v })} options={['日度', '月度', '季度', '年度']} /></td><td><Input value={x.warning} onChange={v => updateIndicator(x.id, { warning: v })} /></td><td><Input value={x.tolerance} onChange={v => updateIndicator(x.id, { tolerance: v })} /></td><td><TextAction onClick={() => set({ indicators: indicators.filter(y => y.id !== x.id) })}>删除</TextAction></td></tr>)}</tbody></Table>{indicators.length === 0 && <div className="inline-empty">暂无指标，请新增或批量导入</div>}</Section><Section title="方案附件"><FileUploader files={files} onChange={setFiles} /></Section></Page>; }

function RiskPreferenceDetail({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.riskPreferences.find(x => x.id === id) || state.riskPreferences[0]; const [tab, setTab] = useState('概览'); return <Page title="风险偏好及目标 - 方案详情" breadcrumb={['预警管理', '风险偏好及目标', item.name]} actions={<><Button variant="secondary" onClick={() => downloadCSV(`${item.code}.csv`, [['方案编号', '方案名称', '状态'], [item.code, item.name, item.status]])}>⇩ 导出</Button><Button variant="secondary" onClick={() => navigate('/warning/risk-preference')}>返回</Button></>}><Section title="基本信息"><div className="detail-grid"><b>方案编号<span>{item.code}</span></b><b>方案名称<span>{item.name}</span></b><b>覆盖机构范围<span>{item.institution}</span></b><b>生效时间<span>{item.effectiveDate} 至 {item.expiryDate}</span></b><b>方案状态<span><StatusTag value={item.status} /></span></b><b>编制部门<span>{item.department}</span></b><b>编制依据<span>{item.basis}</span></b></div></Section><Tabs active={tab} onChange={setTab} items={['概览', '风险偏好指标明细', '方案附件']} />{tab === '概览' && <Section title="方案概览"><div className="read-block"><b>定性风险偏好陈述</b><p>{item.statement}</p><b>方案说明</b><p>{item.summary}</p></div></Section>}{tab === '风险偏好指标明细' && <Section title="风险偏好指标明细"><Table><thead><tr><th>序号</th><th>风险类别</th><th>指标名称</th><th>指标定义</th><th>单位</th><th>适用机构</th><th>监测频率</th><th>预警值</th><th>容忍值</th><th>生效时间</th></tr></thead><tbody>{item.indicators.map((x, i) => <tr key={x.id}><td>{i + 1}</td><td>{x.category}</td><td>{x.name}</td><td>{x.definition}</td><td>{x.unit}</td><td>{x.institution}</td><td>{x.frequency}</td><td>{x.warning}</td><td>{x.tolerance}</td><td>{x.effectiveDate}</td></tr>)}</tbody></Table></Section>}{tab === '方案附件' && <Section title="方案附件"><div className="file-list">{item.attachments.length ? item.attachments.map(x => <div className="file-row" key={x.id}><span>▣ {x.name}</span><small>{formatSize(x.size)}</small><TextAction onClick={() => downloadText(x.name + '.txt', '风险偏好方案附件预览')}>下载</TextAction></div>) : <div className="inline-empty">暂无附件</div>}</div></Section>}<Section title="操作记录"><OperationHistory logs={item.logs} /></Section></Page>; }


function WarningRules({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ code: '', indicator: '', risk: '', institution: '', status: '', running: true }); const [selected, setSelected] = useState<string[]>([]); const [modal, setModal] = useState<WarningRule | null>(null); const items = state.warningRules.filter(x => (!q.code || x.code.includes(q.code)) && (!q.indicator || x.indicator.includes(q.indicator)) && (!q.risk || x.riskType === q.risk) && (!q.institution || x.institution === q.institution) && (!q.status || x.status === q.status) && (!q.running || x.status === '生效')); const toggle = (id: string) => setSelected(v => v.includes(id) ? v.filter(x => x !== id) : [...v, id]); const updateStatus = (item: WarningRule, target: string, reason: string, review: boolean) => { update(s => { const x = s.warningRules.find(y => y.id === item.id)!; warningRuleService.update(x, { status: target as WarningRule['status'] }, review ? '提交状态变更申请' : '状态变更', `${reason}，目标状态：${target}`, role); }); setModal(null); toast(review ? '状态变更申请已提交' : '规则状态已更新'); }; return <Page title="风险预警规则管理" breadcrumb={['预警管理', '风险预警规则管理']} actions={permitted(role, 'rule-config') && <Button onClick={() => navigate('/warning/rules/new/config')}>＋ 预警规则新增</Button>}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ code: '', indicator: '', risk: '', institution: '', status: '', running: true })}><Field label="生效起止时间"><div className="date-range"><Input type="date" /><span>~</span><Input type="date" /></div></Field><Field label="指标风险类型"><Select value={q.risk} onChange={v => setQ({ ...q, risk: v })} options={riskTypes} /></Field><Field label="适用机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field><Field label="规则状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['未生效', '待审核', '生效', '暂停预警', '停用']} /></Field><Field label="规则编号"><Input value={q.code} onChange={v => setQ({ ...q, code: v })} placeholder="请输入规则编号" /></Field><Field label="指标名称"><Input value={q.indicator} onChange={v => setQ({ ...q, indicator: v })} placeholder="请输入指标名称" /></Field><label className="check-field"><input type="checkbox" checked={q.running} onChange={e => setQ({ ...q, running: e.target.checked })} /> 仅展示运行中规则</label></SearchPanel><div className="list-toolbar"><div><Button variant="secondary" onClick={() => toast('批量上传模板已下载')}>＋ 批量规则上传</Button><Button variant="secondary" disabled={!selected.length || !permitted(role, 'state-edit')} onClick={() => selected.forEach(id => update(s => { const item = s.warningRules.find(x => x.id === id); if (item) warningRuleService.update(item, { status: '停用' }, '批量停用', '批量停用预警规则', role); }))}>批量停用</Button><Button variant="secondary" onClick={() => downloadCSV('预警规则.csv', [['规则编号', '指标名称', '状态'], ...items.map(x => [x.code, x.indicator, x.status])])}>⇩ 导出</Button></div><span>共 {items.length} 条</span></div><Table><thead><tr><th><input type="checkbox" checked={selected.length === items.length && items.length > 0} onChange={() => setSelected(selected.length === items.length ? [] : items.map(x => x.id))} /></th><th>序号</th><th>指标名称</th><th>指标风险类型</th><th>适用机构</th><th>监测频率</th><th>规则编号</th><th>规则类型</th><th>黄灯预警规则</th><th>红灯预警规则</th><th>生效时间</th><th>规则状态</th><th>操作</th><th>操作记录</th><th>规则配置</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td><input type="checkbox" checked={selected.includes(item.id)} onChange={() => toggle(item.id)} /></td><td>{i + 1}</td><td>{item.indicator}</td><td>{item.riskType}</td><td>{item.institution}</td><td>{item.frequency}</td><td>{item.code}</td><td>{item.ruleType}</td><td>{item.yellow}</td><td>{item.red}</td><td>{item.effectiveDate}</td><td><StatusTag value={item.status} /></td><td className="actions"><TextAction onClick={() => toast(`${item.code}详情已打开`)}>查看</TextAction><TextAction disabled={!permitted(role, 'rule-config')} onClick={() => navigate(`/warning/rules/${item.id}/config`)}>编辑</TextAction><TextAction disabled={!permitted(role, 'state-edit')} onClick={() => setModal(item)}>状态编辑</TextAction><TextAction onClick={() => update(s => { const x = s.warningRules.find(y => y.id === item.id)!; warningRuleService.update(x, { status: '生效' }, '生效', '规则生效', role); })}>生效</TextAction></td><td><TextAction onClick={() => toast(item.logs.map(x => `${x.time} ${x.operator} ${x.content}`).join('\n'))}>查看</TextAction></td><td><TextAction onClick={() => navigate(`/warning/rules/${item.id}/config`)}>规则配置</TextAction></td></tr>)}</tbody></Table>{modal && <StatusModal item={modal} onClose={() => setModal(null)} onSubmit={updateStatus} />}</Page>; }

function StatusModal({ item, onClose, onSubmit }: { item: WarningRule; onClose: () => void; onSubmit: (item: WarningRule, target: string, reason: string, review: boolean) => void }) { const [target, setTarget] = useState('生效'); const [date, setDate] = useState(today()); const [reason, setReason] = useState(''); const [review, setReview] = useState(true); const [files, setFiles] = useState<Attachment[]>([]); return <Modal title="状态编辑" onClose={onClose} footer={<><Button variant="secondary" onClick={onClose}>取消</Button><Button onClick={() => reason ? onSubmit(item, target, `${date} ${reason}${files.length ? `（附件：${files[0].name}）` : ''}`, review) : window.alert('请输入状态变更原因')}>确认提交</Button></>}><div className="modal-note">规则状态变更将记录至操作记录，可选择是否进入审核流程。</div><div className="detail-grid"><b>规则编号<span>{item.code}</span></b><b>指标名称<span>{item.indicator}</span></b><b>当前状态<span><StatusTag value={item.status} /></span></b></div><div className="form-grid"><Field label="目标状态" required><Select value={target} onChange={setTarget} options={['生效', '停用', '暂停预警']} /></Field><Field label="生效时间" required><Input type="date" value={date} onChange={setDate} /></Field><Field label="状态变更原因" required span={2}><Textarea value={reason} onChange={setReason} /></Field></div><Field label="状态变更附件"><FileUploader files={files} onChange={setFiles} multiple={false} /></Field><label className="check-field"><input type="checkbox" checked={review} onChange={e => setReview(e.target.checked)} /> 提交后进入审核流程</label></Modal>; }

function RuleConfig({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const existing = state.warningRules.find(x => x.id === id); const [rule, setRule] = useState<WarningRule>(() => existing ? structuredClone(existing) : { id: uid('wr'), code: '系统自动生成', indicator: '', riskType: '', institution: '', frequency: '月度', ruleType: '阈值预警', yellow: '', red: '', effectiveDate: '', status: '未生效', nodes: [{ id: uid('node'), threshold: '', light: '黄灯' }, { id: uid('node'), threshold: '', light: '红灯' }], segments: [], pushMethods: ['平台通知'], submitter: role, logs: [] }); const generate = () => { const nodes = rule.nodes.filter(x => x.threshold).sort((a, b) => Number(a.threshold) - Number(b.threshold)); setRule({ ...rule, nodes, yellow: nodes[0] ? `≥${nodes[0].threshold}%` : '', red: nodes[1] ? `≥${nodes[1].threshold}%` : '', segments: [{ name: '区间1', range: `< ${nodes[0]?.threshold || '—'}%`, light: '绿灯（不预警）' }, ...nodes.slice(0, -1).map((x, i) => ({ name: `区间${i + 2}`, range: `${x.threshold}% - ${nodes[i + 1].threshold}%`, light: '黄灯' })), { name: `区间${nodes.length + 1}`, range: `≥ ${nodes[nodes.length - 1]?.threshold || '—'}%`, light: '红灯' }] }); }; const save = (submit: boolean) => { if (!rule.indicator || !rule.institution || !rule.effectiveDate) return toast('请填写规则适用机构、指标名称和生效时间'); update(s => { let item = s.warningRules.find(x => x.id === id); if (!item) { item = warningRuleService.create(s, role); } warningRuleService.update(item, { ...rule, id: item.id, code: item.code, status: submit ? '待审核' : item.status }, submit ? '提交审阅' : '保存草稿', submit ? '预警规则配置提交审阅' : '保存预警规则配置', role); }); toast(submit ? '规则配置已提交审阅' : '规则配置已保存'); navigate('/warning/rules'); }; return <Page title="预警规则管理 - 规则配置" breadcrumb={['预警管理', '预警规则管理', '规则配置']} actions={<><Button variant="secondary" onClick={() => navigate('/warning/rules')}>返回</Button><Button variant="secondary" onClick={() => save(false)}>保存</Button><Button onClick={() => save(true)} disabled={!permitted(role, 'rule-config')}>提交审阅</Button></>}><Section title="基本信息"><div className="form-grid"><Field label="规则适用机构" required><Select value={rule.institution} onChange={v => setRule({ ...rule, institution: v })} options={institutions} /></Field><Field label="指标名称" required><Select value={rule.indicator} onChange={v => setRule({ ...rule, indicator: v })} options={state.indicators.map(x => x.name)} /></Field><Field label="规则类型"><Select value={rule.ruleType} onChange={v => setRule({ ...rule, ruleType: v })} options={['指标绝对值', '同比增幅', '同比绝对值', '环比增幅', '环比绝对值']} /></Field><Field label="生效时间" required><Input type="date" value={rule.effectiveDate} onChange={v => setRule({ ...rule, effectiveDate: v })} /></Field></div></Section><Section title="历史阈值规则"><Table><thead><tr><th>期间</th><th>黄灯预警规则</th><th>红灯预警规则</th><th>变化原因</th></tr></thead><tbody><tr><td>2024-01 至 2024-06</td><td>≥2.00%</td><td>≥5.00%</td><td>年度风险偏好方案发布</td></tr><tr><td>2023-01 至 2023-12</td><td>≥3.00%</td><td>≥6.00%</td><td>—</td></tr></tbody></Table></Section><Section title="预警值分段节点" extra={<Button variant="secondary" onClick={() => setRule({ ...rule, nodes: [...rule.nodes, { id: uid('node'), threshold: '', light: '绿灯（不预警）' }] })}>＋ 新增分段节点</Button>}><Table><thead><tr><th>节点</th><th>阈值（%）</th><th>节点赋灯</th><th>操作</th></tr></thead><tbody>{rule.nodes.map((node, i) => <tr key={node.id}><td>节点{i + 1}</td><td><Input value={node.threshold} onChange={v => setRule({ ...rule, nodes: rule.nodes.map(x => x.id === node.id ? { ...x, threshold: v } : x) })} /></td><td><Select value={node.light} onChange={v => setRule({ ...rule, nodes: rule.nodes.map(x => x.id === node.id ? { ...x, light: v } : x) })} options={['红灯', '黄灯', '绿灯（不预警）']} /></td><td><TextAction onClick={() => setRule({ ...rule, nodes: rule.nodes.filter(x => x.id !== node.id) })}>删除</TextAction></td></tr>)}</tbody></Table><Button variant="secondary" onClick={generate}>生成分段区间</Button></Section><Section title="区间及节点赋灯"><Table><thead><tr><th>区间</th><th>区间范围</th><th>预警灯赋值</th><th>说明</th></tr></thead><tbody>{rule.segments.map((seg, i) => <tr key={seg.name}><td>{seg.name}</td><td>{seg.range}</td><td><Select value={seg.light} onChange={v => setRule({ ...rule, segments: rule.segments.map((x, j) => j === i ? { ...x, light: v } : x) })} options={['红灯', '黄灯', '绿灯（不预警）']} /></td><td>指标值落入区间时触发对应灯号</td></tr>)}</tbody></Table></Section><Section title="推送及提交"><div className="form-grid"><Field label="推送方式"><div className="checks">{['邮件', 'OA系统内', '平台通知'].map(x => <label key={x}><input type="checkbox" checked={rule.pushMethods.includes(x)} onChange={() => setRule({ ...rule, pushMethods: rule.pushMethods.includes(x) ? rule.pushMethods.filter(y => y !== x) : [...rule.pushMethods, x] })} />{x}</label>)}</div></Field><Field label="提交人" required><Input value={rule.submitter} onChange={v => setRule({ ...rule, submitter: v })} /></Field></div></Section></Page>; }

function RuleApprove({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.warningRules.find(x => x.id === id) || state.warningRules[1]; const [opinion, setOpinion] = useState(''); const act = (pass: boolean) => { if (!opinion) return toast('请填写审阅意见'); update(s => { const x = s.warningRules.find(y => y.id === item.id)!; warningRuleService.update(x, { status: pass ? '生效' : '未生效' }, pass ? '审阅通过' : '驳回', opinion, role); }); toast(pass ? '审阅通过，规则已生效' : '已驳回并退回提交人修改'); navigate('/warning/rules'); }; return <Page title="预警规则配置 - 审阅" breadcrumb={['预警管理', '预警规则管理', '规则审阅']} actions={<Button variant="secondary" onClick={() => navigate('/warning/rules')}>返回</Button>}><WorkflowSteps steps={['规则配置', '提交审阅', '管理层审阅', '发布生效']} current={2} /><Section title="规则基本信息"><div className="detail-grid"><b>规则编号<span>{item.code}</span></b><b>适用机构<span>{item.institution}</span></b><b>指标名称<span>{item.indicator}</span></b><b>规则类型<span>{item.ruleType}</span></b><b>黄灯预警规则<span>{item.yellow}</span></b><b>红灯预警规则<span>{item.red}</span></b></div></Section><Section title="规则配置展示"><Table><thead><tr><th>节点</th><th>阈值</th><th>区间</th><th>区间预警灯</th><th>节点赋灯</th></tr></thead><tbody>{item.nodes.map((x, i) => <tr key={x.id}><td>节点{i + 1}</td><td>{x.threshold}%</td><td>{item.segments[i]?.range || '—'}</td><td><StatusTag value={item.segments[i]?.light || '绿灯（不预警）'} /></td><td><StatusTag value={x.light} /></td></tr>)}</tbody></Table><div className="read-row">推送方式：{item.pushMethods.join('、')}　提交人：{item.submitter}</div></Section><Section title="审阅意见"><Field label="审阅意见" required><Textarea value={opinion} onChange={setOpinion} /></Field><div className="form-actions"><Button variant="danger" onClick={() => act(false)}>驳回</Button><Button onClick={() => act(true)}>审阅通过</Button></div></Section></Page>; }

function WarningDisposalList({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ level: '', institution: '', risk: '', indicator: '', status: '' }); const items = state.warningDisposals.filter(x => (!q.level || x.level === q.level) && (!q.institution || x.institution === q.institution) && (!q.risk || x.riskType === q.risk) && (!q.indicator || x.indicator.includes(q.indicator)) && (!q.status || x.status === q.status)); return <Page title="预警提示与处置" breadcrumb={['预警管理', '预警提示与处置']}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ level: '', institution: '', risk: '', indicator: '', status: '' })}><Field label="预警等级"><Select value={q.level} onChange={v => setQ({ ...q, level: v })} options={['黄灯', '红灯']} /></Field><Field label="所属机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field><Field label="风险类型"><Select value={q.risk} onChange={v => setQ({ ...q, risk: v })} options={riskTypes} /></Field><Field label="指标名称"><Input value={q.indicator} onChange={v => setQ({ ...q, indicator: v })} /></Field><Field label="处理状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['待填写原因分析答复', '待提交应对处置方案', '待审阅处置方案', '持续跟踪执行情况', '待评估反馈']} /></Field><Field label="预警时间"><div className="date-range"><Input type="date" /><span>~</span><Input type="date" /></div></Field></SearchPanel><div className="list-toolbar"><span>预警事项列表 · {items.length} 条</span><Button variant="secondary" onClick={() => downloadCSV('预警事项.csv', [['提示函号', '等级', '机构', '状态'], ...items.map(x => [x.letterNo, x.level, x.institution, x.status])])}>⇩ 导出</Button></div><Table><thead><tr><th>序号</th><th>预警等级</th><th>所属机构</th><th>风险类型</th><th>指标名称</th><th>提示函号</th><th>处理状态</th><th>预警时间</th><th>操作</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td><StatusTag value={item.level} /></td><td>{item.institution}</td><td>{item.riskType}</td><td>{item.indicator}</td><td>{item.letterNo}</td><td><StatusTag value={item.status} /></td><td>{item.triggerDate}</td><td><TextAction onClick={() => navigate(`/warning/disposal/${item.id}`)}>查看详情</TextAction></td></tr>)}</tbody></Table><Pagination total={items.length} page={1} setPage={() => undefined} /></Page>; }

function WarningDisposalDetail({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.warningDisposals.find(x => x.id === id) || state.warningDisposals[0]; const isRed = item.level === '红灯'; const [form, setForm] = useState({ reason: item.reason, plan: item.plan, assessment: item.assessment, review: item.review, followUp: item.followUp, releaseAssessment: item.releaseAssessment, expectedReleaseDate: item.expectedReleaseDate }); const [files, setFiles] = useState<Attachment[]>(item.attachments); const save = (submit: boolean) => { if (submit && !form.reason) return toast('请至少填写风险事项描述/原因分析'); update(s => { const x = s.warningDisposals.find(y => y.id === item.id)!; Object.assign(x, form, { attachments: files, status: submit ? (isRed ? '待审阅处置方案' : '持续跟踪执行情况') : x.status, logs: [...x.logs, createLog(submit ? '提交申请' : '保存草稿', submit ? '处置方案已提交后续处理环节' : '保存预警处置草稿', role)] }); }); toast(submit ? '处置信息已提交' : '草稿已保存'); navigate('/warning/disposal'); }; return <Page title={`${isRed ? '重大风险提示函' : '预警提示函'}详情`} breadcrumb={['预警管理', '预警提示与处置', item.letterNo]} actions={<><Button variant="secondary" onClick={() => navigate('/warning/disposal')}>返回</Button><Button variant="secondary" onClick={() => save(false)}>保存草稿</Button><Button onClick={() => save(true)}>{isRed ? '提交申请' : '提交评估'}</Button></>}><WorkflowSteps steps={isRed ? ['系统推送', '金融机构原因分析', '金融机构处置方案', '金融机构管理部门评估', '管理层审阅', '金控公司持续跟进', '解除预警评估'] : ['系统推送预警提示', '金融机构填写原因分析意见', '金融机构提交应对处置方案', '金融机构持续跟进执行情况', '解除预警评估']} current={isRed ? 2 : 3} /><Section title="预警基本信息"><div className="detail-grid"><b>机构名称<span>{item.institution}</span></b><b>指标名称<span>{item.indicator}</span></b><b>指标风险类型<span>{item.riskType}</span></b><b>本期指标值<span>{item.value}</span></b><b>本期预警信号<span><StatusTag value={item.level} /></span></b><b>预警规则<span>{item.rule}</span></b><b>提示编号<span>{item.letterNo}</span></b><b>预警触发日期<span>{item.triggerDate}</span></b></div></Section><Section title="处置填写"><div className="form-grid"><Field label="风险事项描述/情况分析意见" required><Textarea value={form.reason} onChange={v => setForm({ ...form, reason: v })} /></Field><Field label="应对处置方案"><Textarea value={form.plan} onChange={v => setForm({ ...form, plan: v })} /></Field><Field label="金融风险管理部门评估"><Textarea value={form.assessment} onChange={v => setForm({ ...form, assessment: v })} /></Field><Field label="管理层审阅处置方案"><Textarea value={form.review} onChange={v => setForm({ ...form, review: v })} /></Field><Field label="金控公司持续跟踪执行情况"><Textarea value={form.followUp} onChange={v => setForm({ ...form, followUp: v })} /></Field><Field label="解除预警评估"><Textarea value={form.releaseAssessment} onChange={v => setForm({ ...form, releaseAssessment: v })} /></Field><Field label="预计解除日期"><Input type="date" value={form.expectedReleaseDate} onChange={v => setForm({ ...form, expectedReleaseDate: v })} /></Field></div></Section><Section title="附件上传"><FileUploader files={files} onChange={setFiles} /></Section><Section title="处理记录"><OperationHistory logs={item.logs} /></Section></Page>; }

function IndicatorList({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ code: '', name: '', status: '', institution: '' }); const items = state.indicators.filter(x => (!q.code || x.code.includes(q.code)) && (!q.name || x.name.includes(q.name)) && (!q.status || x.status === q.status) && (!q.institution || x.institution === q.institution)); return <Page title="指标新增与维护" breadcrumb={['指标管理', '指标新增与维护']} actions={<Button onClick={() => navigate('/indicators/maintenance/new')}>＋ 新增指标</Button>}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ code: '', name: '', status: '', institution: '' })}><Field label="指标编码"><Input value={q.code} onChange={v => setQ({ ...q, code: v })} /></Field><Field label="指标名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} /></Field><Field label="指标状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['生效', '停用']} /></Field><Field label="适用机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field></SearchPanel><Table><thead><tr><th>序号</th><th>指标编码</th><th>指标名称</th><th>指标状态</th><th>指标定义</th><th>指标类型</th><th>指标子类</th><th>适用机构</th><th>操作</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td className="link" onClick={() => navigate(`/indicators/maintenance/${item.id}`)}>{item.code}</td><td>{item.name}</td><td><StatusTag value={item.status} /></td><td>{item.definition}</td><td>{item.type}</td><td>{item.subtype}</td><td>{item.institution}</td><td><TextAction onClick={() => navigate(`/indicators/maintenance/${item.id}`)}>维护</TextAction><TextAction onClick={() => toast(item.logs.map(x => `${x.time} ${x.action} ${x.content}`).join('\n'))}>查看维护记录</TextAction>{item.status === '生效' && <TextAction onClick={() => update(s => { const x = s.indicators.find(y => y.id === item.id)!; x.status = '停用'; x.logs.push(createLog('停用', '指标已停用', role)); })}>停用</TextAction>}</td></tr>)}</tbody></Table><Pagination total={items.length} page={1} setPage={() => undefined} /></Page>; }

function IndicatorEditor({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const editing = state.indicators.find(x => x.id === id); const [form, setForm] = useState<Partial<Indicator>>(() => editing ? structuredClone(editing) : { name: '', definition: '', institution: '', type: '风险类', subtype: '', managementType: '监测指标', effectiveDate: '', frequency: '月度', sourceTables: [''] }); const set = (patch: Partial<Indicator>) => setForm(x => ({ ...x, ...patch })); const submit = () => { if (!form.name || !form.institution || !form.type || !form.effectiveDate || !(form.sourceTables || []).filter(Boolean).length) return toast('请填写指标名称、适用机构、类型、生效日期和至少一个源头表'); update(s => { if (editing) { const x = s.indicators.find(y => y.id === editing.id)!; const nextVersion = `V${x.versions.length + 1}.0`; x.versions.unshift({ version: nextVersion, operation: '维护', name: form.name || x.name, definition: form.definition || x.definition, effectiveDate: form.effectiveDate || x.effectiveDate, institution: form.institution || x.institution, type: form.type || x.type, subtype: form.subtype || x.subtype, frequency: form.frequency || x.frequency, sourceTable: (form.sourceTables || []).join('、'), stopDate: '—' }); Object.assign(x, form, { logs: [...x.logs, createLog('维护', `生成完整快照 ${nextVersion}`, role)] }); } else indicatorService.create(s, form, role); }); toast(editing ? '指标维护已保存并生成新版本' : '指标已新增，编码自动生成'); navigate('/indicators/maintenance'); }; return <Page title={editing ? '维护指标' : '新增指标'} breadcrumb={['指标管理', '指标新增与维护', editing ? '维护指标' : '新增指标']} actions={<><Button variant="secondary" onClick={() => navigate('/indicators/maintenance')}>关闭</Button><Button onClick={submit}>提交</Button></>}><Section title="基本信息"><div className="form-grid"><Field label="指标编码"><Input value={editing?.code || '系统自动生成'} disabled /></Field><Field label="指标名称" required><Input value={form.name} onChange={v => set({ name: v })} /></Field><Field label="适用机构" required><Select value={form.institution} onChange={v => set({ institution: v })} options={institutions} /></Field><Field label="指标类型" required><Select value={form.type} onChange={v => set({ type: v })} options={['财务类', '资本类', '风险类']} /></Field><Field label="指标子类"><Input value={form.subtype} onChange={v => set({ subtype: v })} /></Field><Field label="指标管理类型"><Select value={form.managementType} onChange={v => set({ managementType: v })} options={['风险限额指标', '监测指标', '会计校验指标']} /></Field><Field label="指标定义" required span={2}><Textarea value={form.definition} onChange={v => set({ definition: v })} /></Field></div></Section><Section title="运行设置"><div className="form-grid"><Field label="生效起始日期" required><Input type="date" value={form.effectiveDate} onChange={v => set({ effectiveDate: v })} /></Field><Field label="监测频率"><Select value={form.frequency} onChange={v => set({ frequency: v })} options={['日度', '月度', '季度', '年度', '发生即报']} /></Field></div></Section><Section title="数据来源" extra={<Button variant="secondary" onClick={() => set({ sourceTables: [...(form.sourceTables || []), ''] })}>＋ 添加源头表</Button>}><div className="source-list">{(form.sourceTables || []).map((source, i) => <div key={i}><Input value={source} onChange={v => set({ sourceTables: (form.sourceTables || []).map((x, j) => j === i ? v : x) })} placeholder="请输入源头表名称" />{(form.sourceTables || []).length > 1 && <TextAction onClick={() => set({ sourceTables: (form.sourceTables || []).filter((_, j) => j !== i) })}>删除</TextAction>}</div>)}</div></Section></Page>; }

function IndicatorVersions({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ code: '', name: '', version: '' }); const [history, setHistory] = useState<Indicator | null>(null); const items = state.indicators.filter(x => (!q.code || x.code.includes(q.code)) && (!q.name || x.name.includes(q.name)) && (!q.version || x.versions.some(v => v.version.includes(q.version)))); return <Page title="指标版本管理" breadcrumb={['指标管理', '指标版本管理']}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ code: '', name: '', version: '' })}><Field label="指标编码"><Input value={q.code} onChange={v => setQ({ ...q, code: v })} /></Field><Field label="指标名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} /></Field><Field label="版本号"><Input value={q.version} onChange={v => setQ({ ...q, version: v })} /></Field></SearchPanel><Table><thead><tr><th>序号</th><th>指标编码</th><th>指标名称</th><th>指标状态</th><th>指标定义</th><th>监测频率</th><th>当前版本号</th><th>操作</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td>{item.code}</td><td>{item.name}</td><td><StatusTag value={item.status} /></td><td>{item.definition}</td><td>{item.frequency}</td><td>{item.versions[0]?.version}</td><td><TextAction onClick={() => setHistory(item)}>查看历史版本</TextAction></td></tr>)}</tbody></Table>{history && <Modal title={`指标历史版本 · ${history.code}`} onClose={() => setHistory(null)} footer={<><Button variant="secondary" onClick={() => setHistory(null)}>关闭</Button><Button onClick={() => downloadCSV(`${history.code}-历史版本.csv`, [['版本号', '维护操作', '指标名称', '生效日期'], ...history.versions.map(v => [v.version, v.operation, v.name, v.effectiveDate])])}>下载</Button></>}><Table><thead><tr><th>版本号</th><th>维护操作</th><th>指标名称</th><th>指标定义</th><th>生效起始日期</th><th>适用机构</th><th>指标类型</th><th>源头表</th><th>停用日期</th></tr></thead><tbody>{history.versions.map(v => <tr key={v.version}><td>{v.version}</td><td>{v.operation}</td><td>{v.name}</td><td>{v.definition}</td><td>{v.effectiveDate}</td><td>{v.institution}</td><td>{v.type}/{v.subtype}</td><td>{v.sourceTable}</td><td>{v.stopDate}</td></tr>)}</tbody></Table></Modal>}</Page>; }

const majorEventWorkflowSteps = ['新增事件', '提交首报及处置方案', '核实并组织汇报', '管理层审阅', '董事会审阅', '执行处置并续报', '终报归档/常态跟踪'];

function MajorEventList({ state, role, navigate, update, toast }: PageProps) {
  const [q, setQ] = useState({ name: '', institution: '', type: '', status: '' });
  const items = state.majorEvents.filter(x => canViewInstitution(role, x.institution) && (!q.name || x.name.includes(q.name)) && (!q.institution || x.institution === q.institution) && (!q.type || x.type === q.type) && (!q.status || x.status === q.status));
  const behindEditorModal = window.location.pathname === '/major-events/new' || window.location.pathname.endsWith('/edit');
  const perform = (action: ReturnType<typeof getMajorEventActions>[number], item: MajorEvent) => {
    if (action === 'view') return navigate(`/major-events/${item.id}`);
    if (action === 'edit' || action === 'submit-first') return navigate(`/major-events/${item.id}/edit`);
    if (action === 'follow-up') return navigate(`/major-events/${item.id}/follow-up`);
    if (action === 'final-report') return navigate(`/major-events/${item.id}/final-report`);
    if (action === 'delete') {
      if (!window.confirm(`确认删除草稿“${item.name}”吗？`)) return;
      update(current => { majorEventService.removeDraft(current, item.id); });
      return toast('重大风险事件草稿已删除');
    }
    if (action === 'history') return toast(item.logs.map(log => `${log.time} ${log.content}`).join('\n'));
    update(current => {
      const target = current.majorEvents.find(event => event.id === item.id);
      if (target) majorEventService.applyManagementAction(target, action, role);
    });
    toast(`${majorEventActionLabels[action]}操作已记录`);
  };
  return <Page title="重大风险事件管理" breadcrumb={['重大风险事件管理']} inline={behindEditorModal}>
    <SearchPanel onSearch={() => undefined} onReset={() => setQ({ name: '', institution: '', type: '', status: '' })}>
      <Field label="事件名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} /></Field>
      <Field label="所属机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={role === '各金融机构' ? [currentInstitution] : institutions} /></Field>
      <Field label="风险事件类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={eventTypes} /></Field>
      <Field label="事件状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['草稿', '待审核', '处理中', '常态跟踪', '已归档']} /></Field>
      <Field label="发生时间"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field>
    </SearchPanel>
    <div className="list-toolbar">
      <span>重大风险事件台账 · {items.length} 条</span>
      <div>
        {permitted(role, 'event-create') && <Button onClick={() => navigate('/major-events/new')}>＋ 新增事件</Button>}
        <Button variant="secondary" onClick={() => downloadCSV('重大风险事件.csv', [['事件编号', '事件名称', '机构', '状态'], ...items.map(x => [x.code, x.name, x.institution, x.status])])}>⇩ 批量导出</Button>
      </div>
    </div>
    <Table><thead><tr><th>序号</th><th>事件编号</th><th>事件名称</th><th>所属机构</th><th>风险事件类型</th><th>发生时间</th><th>最新报送类型</th><th>当前环节</th><th>事件状态</th><th>操作</th><th>事件流程</th></tr></thead><tbody>{items.map((item, i) => { const actions = getMajorEventActions(role, item); return <tr key={item.id}><td>{i + 1}</td><td>{item.code}</td><td>{item.name}</td><td>{item.institution}</td><td>{item.type}</td><td>{item.occurredAt}</td><td>{item.latestReport}</td><td>{item.currentStage}</td><td><StatusTag value={item.status} /></td><td>{actions.filter(action => action !== 'history').map(action => <TextAction key={action} onClick={() => perform(action, item)}>{majorEventActionLabels[action]}</TextAction>)}</td><td>{actions.includes('history') && <TextAction onClick={() => perform('history', item)}>查看流程</TextAction>}</td></tr>; })}</tbody></Table>
    <Pagination total={items.length} page={1} setPage={() => undefined} />
  </Page>;
}

function MajorEventEditor({ state, role, navigate, update, toast }: PageProps) {
  const editingId = window.location.pathname.endsWith('/edit') ? window.location.pathname.split('/')[2] : undefined;
  const editing = state.majorEvents.find(event => event.id === editingId);
  const [form, setForm] = useState<Partial<MajorEvent>>(() => editing ? structuredClone(editing) : { name: '', institution: currentInstitution, type: '', occurredAt: '', impact: '', contact: '', phone: '', basic: '', analysis: '', measures: '', trend: '', target: '', plan: '', responsibleDept: '', responsible: '', deadline: '' });
  const [files, setFiles] = useState<Attachment[]>(editing?.attachments || []);
  const set = (patch: Partial<MajorEvent>) => setForm(value => ({ ...value, ...patch }));
  const close = () => navigate('/major-events');
  const save = (mode: 'draft' | 'submit') => {
    if (!form.name?.trim()) return toast('请至少填写事件名称后保存草稿');
    if (mode === 'submit' && (!form.type || !form.institution || !form.occurredAt || !form.basic?.trim())) return toast('请填写事件名称、风险事件类型、所属机构、发生时间和事件基本情况');
    update(current => {
      const value = { ...form, institution: currentInstitution, name: form.name?.trim(), basic: form.basic?.trim(), attachments: files };
      const target = editing ? current.majorEvents.find(event => event.id === editing.id) : undefined;
      if (target) majorEventService.update(target, value, role, mode);
      else majorEventService.create(current, value, role, mode);
    });
    toast(mode === 'draft' ? '重大风险事件草稿已保存' : '重大风险事件首报已提交申请');
    close();
  };
  const descriptionLimit = 1000;
  const permittedToEdit = editingId ? !!editing && canEditMajorEvent(role, editing) : can(role, 'event-create', { institution: currentInstitution });
  return <>
    <MajorEventList state={state} role={role} navigate={navigate} update={update} toast={toast} />
    <Page title={editing ? '编辑重大风险事件（首报及处置方案）' : '新增重大风险事件（首报及处置方案）'} breadcrumb={['重大风险事件管理', editing ? '编辑事件' : '新增事件']} onClose={close} hidePageTitle>
      {!permittedToEdit ? <div className="empty-state"><div className="empty-icon">!</div><h2>当前角色无权编辑重大风险事件</h2><p>仅各金融机构可新增本机构事件或编辑本机构草稿。</p></div> : <>
      <WorkflowSteps steps={majorEventWorkflowSteps} current={0} />
      <Section title="事件基本信息"><div className="form-grid">
        <Field label="事件编号"><Input value={editing?.code || majorEventService.nextCode(state)} disabled /></Field>
        <Field label="事件名称" required><Input value={form.name} onChange={value => set({ name: value })} /></Field>
        <Field label="风险事件类型" required><Select value={form.type} onChange={value => set({ type: value })} options={eventTypes} /></Field>
        <Field label="所属机构"><Input value={currentInstitution} disabled /></Field>
        <Field label="发生时间" required><Input type="date" value={form.occurredAt} onChange={value => set({ occurredAt: value })} /></Field>
        <Field label="最新报送类型"><Input value={editing?.latestReport || '首报'} disabled /></Field>
        <Field label="当前环节"><Input value={editing?.currentStage || '新增事件'} disabled /></Field>
        <Field label="事件状态"><Input value={editing?.status || '草稿'} disabled /></Field>
        <Field label="影响范围"><Input value={form.impact} onChange={value => set({ impact: value })} placeholder="集团内、机构内、外部影响等" /></Field>
        <Field label="联系人"><div className="contact-fields"><Input value={form.contact} onChange={value => set({ contact: value })} placeholder="联系人" /><Input value={form.phone} onChange={value => set({ phone: value })} placeholder="联系电话" /></div></Field>
      </div></Section>
      <Section title="首报信息"><div className="form-grid">
        <Field label="事件基本情况" required><Textarea value={form.basic} onChange={value => set({ basic: value })} maxLength={descriptionLimit} showCount /></Field>
        <Field label="初步分析研判"><Textarea value={form.analysis} onChange={value => set({ analysis: value })} maxLength={descriptionLimit} showCount /></Field>
        <Field label="已采取措施"><Textarea value={form.measures} onChange={value => set({ measures: value })} maxLength={descriptionLimit} showCount /></Field>
        <Field label="发展趋势"><Textarea value={form.trend} onChange={value => set({ trend: value })} maxLength={descriptionLimit} showCount /></Field>
      </div></Section>
      <Section title="处置方案"><div className="form-grid">
        <Field label="处置目标"><Textarea value={form.target} onChange={value => set({ target: value })} /></Field>
        <Field label="责任部门"><Select value={form.responsibleDept} onChange={value => set({ responsibleDept: value })} options={departments} /></Field>
        <Field label="责任人"><Input value={form.responsible} onChange={value => set({ responsible: value })} /></Field>
        <Field label="计划完成时间"><Input type="date" value={form.deadline} onChange={value => set({ deadline: value })} /></Field>
        <Field label="处置措施" span={2}><Textarea value={form.plan} onChange={value => set({ plan: value })} /></Field>
      </div></Section>
      <Section title="附件上传"><FileUploader files={files} onChange={setFiles} /></Section>
      <Section title="审阅及处理记录">{editing?.logs.length ? <OperationHistory logs={editing.logs} /> : <div className="inline-empty">保存后将生成操作记录</div>}</Section>
      <div className="form-actions major-event-form-actions">
        <Button variant="secondary" onClick={() => save('draft')}>保存草稿</Button>
        <Button onClick={() => save('submit')}>提交申请</Button>
        <Button variant="secondary" onClick={close}>返回</Button>
      </div>
      </>}
    </Page>
  </>;
}

function MajorEventDetail({ state, role, navigate, update, toast }: PageProps) {
  const id = window.location.pathname.split('/')[2];
  const item = state.majorEvents.find(event => event.id === id);
  if (!item || !canViewInstitution(role, item.institution)) return <Page title="重大风险事件详情" breadcrumb={['重大风险事件管理']} actions={<Button variant="secondary" onClick={() => navigate('/major-events')}>返回</Button>}><div className="empty-state"><div className="empty-icon">!</div><h2>无权查看该重大风险事件</h2><p>各金融机构仅可查看本机构数据。</p></div></Page>;
  return <Page title="重大风险事件详情" breadcrumb={['重大风险事件管理', item.code]} actions={<><Button variant="secondary" onClick={() => navigate('/major-events')}>返回</Button><Button variant="secondary" onClick={() => downloadCSV(`${item.code}.csv`, [['事件编号', '事件名称', '状态'], [item.code, item.name, item.status]])}>⇩ 导出</Button></>}>
    <WorkflowSteps steps={majorEventWorkflowSteps} current={item.status === '已归档' ? 6 : item.followUps.length ? 5 : item.status === '待审核' ? 2 : 1} />
    <Section title="事件基本信息"><div className="detail-grid"><b>事件编号<span>{item.code}</span></b><b>事件名称<span>{item.name}</span></b><b>风险事件类型<span>{item.type}</span></b><b>所属机构<span>{item.institution}</span></b><b>发生时间<span>{item.occurredAt}</span></b><b>最新报送类型<span>{item.latestReport}</span></b><b>当前环节<span>{item.currentStage}</span></b><b>事件状态<span><StatusTag value={item.status} /></span></b><b>影响范围<span>{item.impact}</span></b><b>联系人<span>{item.contact} / {item.phone}</span></b></div></Section>
    <Section title="首报信息"><div className="read-block"><b>事件基本情况</b><p>{item.basic}</p><b>初步分析研判</b><p>{item.analysis}</p><b>已采取措施</b><p>{item.measures}</p><b>发展趋势</b><p>{item.trend}</p></div></Section>
    <Section title="处置方案"><div className="detail-grid"><b>处置目标<span>{item.target}</span></b><b>责任部门<span>{item.responsibleDept}</span></b><b>责任人<span>{item.responsible}</span></b><b>计划完成时间<span>{item.deadline}</span></b></div><p className="read-paragraph">{item.plan}</p></Section>
    {item.followUps.length > 0 && <Section title="续报记录">{item.followUps.map((report, index) => <div className="report-block" key={index}><b>第 {index + 1} 次续报 · {report.date}</b><p>最新进展：{report.latestProgress}</p><p>风险变化：{report.riskChange}</p><p>措施执行情况：{report.execution}</p><p>下一步安排：{report.nextStep}</p></div>)}</Section>}
    {item.finalReport && <Section title="终报记录"><div className="report-block"><b>终报 · {item.finalReport.date}</b><p>最终处置结果：{item.finalReport.result}</p><p>实际影响：{item.finalReport.impact}</p><p>风险解除情况：{item.finalReport.release}</p><p>后续管理安排：{item.finalReport.followUp}</p></div></Section>}
    <Section title="审阅及处理记录"><OperationHistory logs={item.logs} /></Section>
  </Page>;
}

function EventFollowUp({ state, role, navigate, update, toast }: PageProps) {
  const id = window.location.pathname.split('/')[2];
  const item = state.majorEvents.find(event => event.id === id);
  const [form, setForm] = useState({ latestProgress: '', riskChange: '', execution: '', nextStep: '' });
  const [files, setFiles] = useState<Attachment[]>([]);
  if (!item || !can(role, 'event-progress', { institution: item.institution })) return <Page title="重大风险事件 - 续报" breadcrumb={['重大风险事件管理']} actions={<Button variant="secondary" onClick={() => navigate('/major-events')}>返回</Button>}><div className="empty-state"><div className="empty-icon">!</div><h2>当前角色无权提交该事件续报</h2></div></Page>;
  const submit = () => {
    if (!form.latestProgress || !form.riskChange || !form.execution || !form.nextStep) return toast('请完整填写续报信息');
    update(current => {
      const target = current.majorEvents.find(event => event.id === item.id);
      if (!target) return;
      target.followUps.push({ ...form, attachments: files, date: today() });
      target.latestReport = '续报';
      target.currentStage = '续报跟踪';
      target.status = '处理中';
      target.logs.push(createLog('续报', '提交事件最新进展续报', role));
    });
    toast('续报已提交');
    navigate(`/major-events/${item.id}`);
  };
  return <Page title="重大风险事件 - 续报" breadcrumb={['重大风险事件管理', item.code, '续报']} actions={<><Button variant="secondary" onClick={() => navigate(`/major-events/${item.id}`)}>返回</Button><Button onClick={submit}>提交续报</Button></>}><Section title="当前事件"><div className="detail-grid"><b>事件编号<span>{item.code}</span></b><b>事件名称<span>{item.name}</span></b><b>当前状态<span><StatusTag value={item.status} /></span></b></div></Section><Section title="续报信息"><div className="form-grid"><Field label="最新进展" required><Textarea value={form.latestProgress} onChange={value => setForm({ ...form, latestProgress: value })} /></Field><Field label="风险变化" required><Textarea value={form.riskChange} onChange={value => setForm({ ...form, riskChange: value })} /></Field><Field label="措施执行情况" required><Textarea value={form.execution} onChange={value => setForm({ ...form, execution: value })} /></Field><Field label="下一步安排" required><Textarea value={form.nextStep} onChange={value => setForm({ ...form, nextStep: value })} /></Field></div></Section><Section title="附件"><FileUploader files={files} onChange={setFiles} /></Section></Page>;
}

function EventFinalReport({ state, role, navigate, update, toast }: PageProps) {
  const id = window.location.pathname.split('/')[2];
  const item = state.majorEvents.find(event => event.id === id);
  const [form, setForm] = useState({ result: '', impact: '', release: '', followUp: '' });
  const [files, setFiles] = useState<Attachment[]>([]);
  if (!item || !can(role, 'event-progress', { institution: item.institution })) return <Page title="重大风险事件 - 终报" breadcrumb={['重大风险事件管理']} actions={<Button variant="secondary" onClick={() => navigate('/major-events')}>返回</Button>}><div className="empty-state"><div className="empty-icon">!</div><h2>当前角色无权提交该事件终报</h2></div></Page>;
  const submit = () => {
    if (!form.result || !form.impact || !form.release || !form.followUp) return toast('请完整填写终报信息');
    update(current => {
      const target = current.majorEvents.find(event => event.id === item.id);
      if (!target) return;
      target.finalReport = { ...form, attachments: files, date: today() };
      target.latestReport = '终报';
      target.currentStage = form.release.includes('未') ? '常态化跟踪' : '终报完成';
      target.status = form.release.includes('未') ? '常态跟踪' : '已归档';
      target.logs.push(createLog('终报', target.status === '已归档' ? '提交终报并归档' : '提交终报并转入常态化跟踪', role));
    });
    toast('终报已提交');
    navigate(`/major-events/${item.id}`);
  };
  return <Page title="重大风险事件 - 终报" breadcrumb={['重大风险事件管理', item.code, '终报']} actions={<><Button variant="secondary" onClick={() => navigate(`/major-events/${item.id}`)}>返回</Button><Button onClick={submit}>提交终报</Button></>}><Section title="终报信息"><div className="form-grid"><Field label="最终处置结果" required><Textarea value={form.result} onChange={value => setForm({ ...form, result: value })} /></Field><Field label="实际影响" required><Textarea value={form.impact} onChange={value => setForm({ ...form, impact: value })} /></Field><Field label="风险解除情况" required><Textarea value={form.release} onChange={value => setForm({ ...form, release: value })} placeholder="已解除或未完全解除" /></Field><Field label="后续管理安排" required><Textarea value={form.followUp} onChange={value => setForm({ ...form, followUp: value })} /></Field></div></Section><Section title="附件"><FileUploader files={files} onChange={setFiles} /></Section></Page>;
}

function Reports({ state, role, navigate, update, toast }: PageProps) { const [tab, setTab] = useState('报表查看'); const [q, setQ] = useState({ name: '', institution: '', type: '' }); const items = state.reports.filter(x => (!q.name || x.name.includes(q.name)) && (!q.institution || x.institution === q.institution) && (!q.type || x.type === q.type)); return <Page title="报表中心" breadcrumb={['报表监测']} actions={<Button onClick={() => navigate('/reports/upload')}>＋ 报表报送</Button>}><Tabs items={['报表查看', '报表报送']} active={tab} onChange={x => { setTab(x); if (x === '报表报送') navigate('/reports/upload'); }} />{tab === '报表查看' && <><SearchPanel onSearch={() => undefined} onReset={() => setQ({ name: '', institution: '', type: '' })}><Field label="报表名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} /></Field><Field label="报送机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field><Field label="报表类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={['财务报表', '风险监测报表', '监管报表']} /></Field><Field label="报表日期"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="报送日期"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><label className="check-field"><input type="checkbox" /> 仅显示我可查看的机构</label></SearchPanel><Table><thead><tr><th>序号</th><th>报表编码</th><th>报表名称</th><th>报送机构</th><th>报表类型</th><th>最新报表日期</th><th>最新报送日期</th><th>报送状态</th><th>操作</th></tr></thead><tbody>{items.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td>{item.code}</td><td>{item.name}</td><td>{item.institution}</td><td>{item.type}</td><td>{item.latestReportDate}</td><td>{item.latestSubmitDate}</td><td><StatusTag value={item.status} /></td><td><TextAction onClick={() => navigate(`/reports/${item.id}/submissions`)}>查看明细</TextAction><TextAction onClick={() => downloadText(`${item.code}.txt`, `${item.name}\n最新报表日期：${item.latestReportDate}`)}>下载</TextAction></td></tr>)}</tbody></Table><Pagination total={items.length} page={1} setPage={() => undefined} /></>}</Page>; }

function ReportSubmissions({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[2]; const report = state.reports.find(x => x.id === id) || state.reports[0]; return <Page title="报送明细" breadcrumb={['报表中心', report.name, '报送明细']} actions={<Button variant="secondary" onClick={() => navigate('/reports')}>返回</Button>}><Section title="报表基本信息"><div className="detail-grid"><b>报表编号<span>{report.code}</span></b><b>报表名称<span>{report.name}</span></b><b>报送机构<span>{report.institution}</span></b><b>报表类型<span>{report.type}</span></b><b>报送频率<span>{report.frequency}</span></b><b>报表说明<span>{report.description}</span></b></div></Section><Section title="历次报送记录"><Table><thead><tr><th>序号</th><th>报送文件流水号</th><th>报表日期</th><th>报送日期</th><th>报送时间</th><th>报送人</th><th>报送说明</th><th>操作</th></tr></thead><tbody>{report.submissions.map((item, i) => <tr key={item.id}><td>{i + 1}</td><td>{item.serial}</td><td>{item.reportDate}</td><td>{item.submitDate}</td><td>{item.submitTime}</td><td>{item.submitter}</td><td>{item.note}</td><td><TextAction onClick={() => toast(`在线查看：${item.serial}`)}>在线查看</TextAction><TextAction onClick={() => downloadText(`${item.serial}.txt`, `${report.name}\n${item.note}`)}>下载</TextAction></td></tr>)}</tbody></Table></Section></Page>; }

function ReportUpload({ state, role, navigate, update, toast }: PageProps) { const [form, setForm] = useState({ report: '', type: '', date: '', note: '' }); const [files, setFiles] = useState<Attachment[]>([]); const report = state.reports.find(x => x.id === form.report); const submit = () => { if (!form.report || !form.type || !form.date || !files.length) return toast('请填写报表编号、报表类型、报表日期并上传附件'); update(s => { const item = s.reports.find(x => x.id === form.report); if (!item) return; reportService.addSubmission(item, { serial: `SUB-${Date.now()}`, reportDate: form.date, submitDate: today(), submitTime: new Date().toLocaleTimeString('zh-CN', { hour12: false }), submitter: role, note: form.note, files }, role); }); toast('报表报送记录已形成'); navigate('/reports'); }; return <Page title="报表上传" breadcrumb={['报表中心', '报表报送']} actions={<><Button variant="secondary" onClick={() => navigate('/reports')}>取消</Button><Button onClick={submit}>提交</Button></>}><Section title="报表基本信息"><div className="form-grid"><Field label="报表编号" required><Select value={form.report} onChange={v => setForm({ ...form, report: state.reports.find(x => x.code === v)?.id || v })} options={state.reports.map(x => x.code)} /></Field><Field label="报表名称" required><Select value={form.report} onChange={v => setForm({ ...form, report: state.reports.find(x => x.name === v)?.id || v })} options={state.reports.map(x => x.name)} /></Field><Field label="报表类型" required><Select value={form.type} onChange={v => setForm({ ...form, type: v })} options={['财务报表', '风险监测报表', '监管报表']} /></Field><Field label="报表日期" required><Input type="date" value={form.date} onChange={v => setForm({ ...form, date: v })} /></Field></div></Section><Section title="附件上传"><FileUploader files={files} onChange={setFiles} /></Section><Section title="报送说明"><Field label="报送说明"><Textarea value={form.note} onChange={v => setForm({ ...form, note: v })} /></Field></Section></Page>; }

function PeriodicReports({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ name: '', institution: '', type: '', cycle: '' }); const items = state.periodicReports.filter(x => (!q.name || x.name.includes(q.name)) && (!q.institution || x.institution === q.institution) && (!q.type || x.type === q.type) && (!q.cycle || x.cycle === q.cycle)); const del = (item: PeriodicReport) => { if (!window.confirm(`确认删除“${item.name}”吗？`)) return; update(s => { s.periodicReports = s.periodicReports.filter(x => x.id !== item.id); }); toast('报告已删除'); }; return <Page title="定期风险报告管理" breadcrumb={['定期报告']} actions={<Button onClick={() => navigate('/periodic-reports/upload')}>＋ 报告上传</Button>}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ name: '', institution: '', type: '', cycle: '' })}><Field label="报告名称"><Input value={q.name} onChange={v => setQ({ ...q, name: v })} /></Field><Field label="报送日期起止"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="报送机构"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field><Field label="报告类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={['全面风险管理报告', '风险监测报告']} /></Field><Field label="周期性"><Select value={q.cycle} onChange={v => setQ({ ...q, cycle: v })} options={['周', '月度', '季度', '年度']} /></Field></SearchPanel><Table><thead><tr><th>报送日期</th><th>报告日期</th><th>定期风险报告名称</th><th>报送机构</th><th>报告类型</th><th>周期性</th><th>报告概述</th><th>附件</th><th>操作</th></tr></thead><tbody>{items.map(item => <tr key={item.id}><td>{item.submitDate}</td><td>{item.reportDate}</td><td>{item.name}</td><td>{item.institution}</td><td>{item.type}</td><td>{item.cycle}</td><td className="ellipsis">{item.overview}</td><td>{item.attachments.length ? '有附件' : '无附件'}</td><td><TextAction onClick={() => downloadText(`${item.name}.txt`, `${item.name}\n${item.overview}`)}>查看下载</TextAction><TextAction onClick={() => navigate(`/periodic-reports/${item.id}/edit`)}>编辑</TextAction><TextAction onClick={() => del(item)}>删除</TextAction></td></tr>)}</tbody></Table><Pagination total={items.length} page={1} setPage={() => undefined} /></Page>; }


function PeriodicReportEditor({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[2]; const existing = state.periodicReports.find(x => x.id === id); const [form, setForm] = useState<Partial<PeriodicReport>>(() => existing ? structuredClone(existing) : { name: '', institution: '上海农商银行', type: '全面风险管理报告', reportDate: '', cycle: '月度', overview: '', visibleInstitutions: ['上海农商银行'], visibleDepartments: ['金融机构管理部'], viewers: [], pushMethod: '平台通知', attachments: [] }); const [files, setFiles] = useState<Attachment[]>(form.attachments || []); const set = (patch: Partial<PeriodicReport>) => setForm(x => ({ ...x, ...patch })); const submit = (draft: boolean) => { if (!form.name || !form.type || !form.reportDate || !form.cycle) return toast('请填写报告名称、类型、日期、周期'); update(s => { let item = existing ? s.periodicReports.find(x => x.id === existing.id)! : periodicReportService.create(s, { ...form, attachments: files }, role); if (existing) Object.assign(item, form, { attachments: files, status: draft ? '草稿' : '已提交', logs: [...item.logs, createLog(draft ? '保存草稿' : '提交', draft ? '保存报告草稿' : '提交定期风险报告', role)] }); else if (!draft) item.status = '已提交'; }); toast(draft ? '报告草稿已保存' : '定期风险报告已提交'); navigate('/periodic-reports'); }; return <Page title={existing ? '定期风险报告 - 编辑' : '定期风险报告 - 报告上传'} breadcrumb={['定期报告', existing ? '编辑' : '报告上传']} actions={<><Button variant="secondary" onClick={() => navigate('/periodic-reports')}>关闭</Button><Button variant="secondary" onClick={() => submit(true)}>保存草稿</Button><Button onClick={() => submit(false)}>提交</Button></>}><Section title="当前报告信息"><div className="detail-grid"><b>当前报告名称<span>{existing?.name || '新建报告'}</span></b><b>报送机构<span>{existing?.institution || form.institution}</span></b><b>当前报告类型<span>{existing?.type || form.type}</span></b><b>当前报告日期<span>{existing?.reportDate || form.reportDate || '—'}</span></b></div></Section><Section title="报告基本信息"><div className="form-grid"><Field label="报告名称" required><Input value={form.name} onChange={v => set({ name: v })} /></Field><Field label="报送机构"><Select value={form.institution} onChange={v => set({ institution: v })} options={institutions} /></Field><Field label="报告类型" required><Select value={form.type} onChange={v => set({ type: v })} options={['全面风险管理报告', '风险监测报告']} /></Field><Field label="报告日期" required><Input type="date" value={form.reportDate} onChange={v => set({ reportDate: v })} /></Field><Field label="周期性" required><div className="checks">{(['周', '月度', '季度', '年度'] as const).map(x => <label key={x}><input type="radio" checked={form.cycle === x} onChange={() => set({ cycle: x })} />{x}</label>)}</div></Field><Field label="报告概述" span={2}><Textarea value={form.overview} onChange={v => set({ overview: v })} /></Field></div></Section><Section title="附件上传"><FileUploader files={files} onChange={setFiles} /></Section><Section title="推送设置"><div className="form-grid"><Field label="推送方式"><Select value={form.pushMethod} onChange={v => set({ pushMethod: v })} options={["邮件", "平台通知", "OA系统内"]} /></Field></div></Section></Page>; }
function SpecialRiskDrafts({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ type: '', institution: '' }); const [expanded, setExpanded] = useState<string[]>([]); const items = state.specialRisks.filter(x => (!q.type || x.types.includes(q.type)) && (!q.institution || x.institutions.includes(q.institution))); const del = (item: SpecialRisk) => { if (!window.confirm(`确认删除“${item.name}”吗？`)) return; update(s => { s.specialRisks = s.specialRisks.filter(x => x.id !== item.id); }); toast('草稿已删除'); }; return <Page title="新建专项风险提示" breadcrumb={['专项风险管理', '新建专项风险提示']} actions={<Button onClick={() => navigate('/special-risks/new')}>＋ 新建专项风险提示</Button>}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ type: '', institution: '' })}><Field label="创建起止时间"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="专项风险类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={specialTypes} /></Field><Field label="下发对象"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field></SearchPanel><Table><thead><tr><th>展开</th><th>创建时间</th><th>上次更新时间</th><th>下发对象</th><th>专项风险类型</th><th>专项风险提示名称</th><th>状态</th><th>操作</th></tr></thead><tbody>{items.map(item => <React.Fragment key={item.id}><tr key={item.id}><td><TextAction onClick={() => setExpanded(v => v.includes(item.id) ? v.filter(x => x !== item.id) : [...v, item.id])}>{expanded.includes(item.id) ? '收起' : '展开'}</TextAction></td><td>{item.createdAt}</td><td>{item.updatedAt}</td><td>{item.institutions.join('、')}</td><td>{item.types.join('、')}</td><td>{item.name}</td><td><StatusTag value={item.status} /></td><td><TextAction onClick={() => navigate(`/special-risks/manage/${item.id}`)}>编辑</TextAction><TextAction onClick={() => del(item)}>删除</TextAction><TextAction onClick={() => downloadText(`${item.name}.txt`, item.purpose)}>下载</TextAction></td></tr>{expanded.includes(item.id) && <tr className="sub-row" key={`${item.id}-detail`}><td colSpan={8}>下级记录：{item.workOrders.length ? item.workOrders.map(x => `${x.id} · ${x.institution} · ${x.status}`).join('　') : '暂无已下发工单'}</td></tr>}</React.Fragment>)}</tbody></Table><Pagination total={items.length} page={1} setPage={() => undefined} /></Page>; }

function SpecialRiskEditor({ state, role, navigate, update, toast }: PageProps) { const [form, setForm] = useState({ name: '', types: [] as string[], institutions: [] as string[], notes: {} as Record<string, string>, purpose: '', measures: '', requirements: '' }); const [files, setFiles] = useState<Attachment[]>([]); const toggle = (list: string[], item: string) => list.includes(item) ? list.filter(x => x !== item) : [...list, item]; const save = (publish: boolean) => { if (!form.name || !form.types.length || !form.institutions.length || !form.purpose || !form.measures || !form.requirements) return toast('请填写名称、专项风险类型、下发机构和三段提示内容'); update(s => { const item = specialRiskService.create(s, { ...form, attachments: files }, role); if (publish) specialRiskService.publish(item, role); }); toast(publish ? `已下发至 ${form.institutions.length} 家机构并生成工单` : '专项风险提示草稿已保存'); navigate('/special-risks/drafts'); }; return <Page title="专项风险提示 - 新建提示" breadcrumb={['专项风险管理', '新建专项风险提示', '新建提示']} actions={<><Button variant="secondary" onClick={() => navigate('/special-risks/drafts')}>关闭</Button><Button variant="secondary" onClick={() => save(false)}>保存草稿</Button><Button onClick={() => save(true)}>提交并下发</Button></>}><Section title="基本信息"><div className="form-grid"><Field label="专项风险提示名称" required><Input value={form.name} onChange={v => setForm({ ...form, name: v })} /></Field><Field label="专项风险提示类型" required><div className="checks">{specialTypes.map(x => <label key={x}><input type="checkbox" checked={form.types.includes(x)} onChange={() => setForm({ ...form, types: toggle(form.types, x) })} />{x}</label>)}</div></Field></div></Section><Section title="下发机构"><div className="institution-check-grid">{institutions.map(x => <div className={form.institutions.includes(x) ? 'selected' : ''} key={x}><label><input type="checkbox" checked={form.institutions.includes(x)} onChange={() => setForm({ ...form, institutions: toggle(form.institutions, x) })} />{x}</label>{form.institutions.includes(x) && <Input value={form.notes[x] || ''} onChange={v => setForm({ ...form, notes: { ...form.notes, [x]: v } })} placeholder="该机构补充信息" />}</div>)}</div></Section><Section title="提示内容"><div className="form-grid"><Field label="提示背景与目的" required><Textarea value={form.purpose} onChange={v => setForm({ ...form, purpose: v })} /></Field><Field label="专项风险提示措施与建议" required><Textarea value={form.measures} onChange={v => setForm({ ...form, measures: v })} /></Field><Field label="机构自检与反馈要求" required><Textarea value={form.requirements} onChange={v => setForm({ ...form, requirements: v })} /></Field></div></Section><Section title="附件上传"><FileUploader files={files} onChange={setFiles} /></Section></Page>; }

function SpecialRiskManage({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ type: '', status: '', institution: '' }); const [expanded, setExpanded] = useState<string[]>([]); const items = state.specialRisks.filter(x => (!q.type || x.types.includes(q.type)) && (!q.institution || x.institutions.includes(q.institution))); const rows = items.flatMap(item => [{ item, order: undefined }, ...(expanded.includes(item.id) ? item.workOrders.map(order => ({ item, order })) : [])]); return <Page title="专项风险提示与管理" breadcrumb={['专项风险管理', '专项风险提示与管理']}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ type: '', status: '', institution: '' })}><Field label="下发起止时间"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="专项风险类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={specialTypes} /></Field><Field label="状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['待反馈', '已反馈', '评估中', '部分解除', '已解除', '待跟踪反馈']} /></Field><Field label="下发对象"><Select value={q.institution} onChange={v => setQ({ ...q, institution: v })} options={institutions} /></Field></SearchPanel><Table><thead><tr><th>展开</th><th>工单编号</th><th>下发日期</th><th>下发对象</th><th>专项风险类型</th><th>提示名称</th><th>状态</th><th>解除日期</th><th>操作</th></tr></thead><tbody>{rows.map(({ item, order }) => order ? <tr className="sub-row" key={order.id}><td>↳</td><td>{order.id}</td><td>{order.issuedAt}</td><td>{order.institution}</td><td>{item.types.join('、')}</td><td>{item.name}</td><td><StatusTag value={order.status} /></td><td>{order.evaluation?.result === '解除' ? order.evaluation.date : '—'}</td><td><TextAction onClick={() => navigate(`/special-risks/manage/${item.id}?order=${order.id}`)}>查看提示</TextAction><TextAction disabled={!order.feedback} onClick={() => navigate(`/special-risks/feedback/${item.id}/evaluate?order=${order.id}`)}>查看管理报告</TextAction></td></tr> : <tr key={item.id}><td><TextAction onClick={() => setExpanded(v => v.includes(item.id) ? v.filter(x => x !== item.id) : [...v, item.id])}>{expanded.includes(item.id) ? '收起' : '展开'}</TextAction></td><td>{item.workOrders[0]?.id || '—'}</td><td>{item.createdAt}</td><td>{item.institutions.join('、')}</td><td>{item.types.join('、')}</td><td>{item.name}</td><td><StatusTag value={item.status === '已下发' ? (item.workOrders.some(x => x.status === '待反馈') ? '待反馈' : '已反馈') : item.status} /></td><td>—</td><td><TextAction onClick={() => navigate(`/special-risks/manage/${item.id}`)}>查看提示</TextAction></td></tr>)}</tbody></Table><Pagination total={rows.length} page={1} setPage={() => undefined} /></Page>; }

function SpecialRiskView({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.specialRisks.find(x => x.id === id) || state.specialRisks[0]; return <Page title="专项风险提示与管理 - 查看提示" breadcrumb={['专项风险管理', '专项风险提示与管理', item.name]} actions={<><Button variant="secondary" onClick={() => navigate('/special-risks/manage')}>关闭</Button><Button variant="secondary" onClick={() => downloadText(`${item.name}.txt`, `${item.purpose}\n${item.measures}\n${item.requirements}`)}>附件下载</Button><Button variant="secondary" onClick={() => downloadText(`${item.name}-管理报告.txt`, item.workOrders.map(x => `${x.institution}：${x.status}`).join('\n'))}>报告下载</Button></>}><Section title="提示基本信息"><div className="detail-grid"><b>专项风险提示名称<span>{item.name}</span></b><b>专项风险类型<span>{item.types.join('、')}</span></b><b>下发机构<span>{item.institutions.join('、')}</span></b><b>创建时间<span>{item.createdAt}</span></b></div><div className="read-block"><b>提示背景与目的</b><p>{item.purpose}</p><b>管理措施与建议</b><p>{item.measures}</p><b>自检与反馈要求</b><p>{item.requirements}</p></div></Section><Section title="金融机构反馈与评估"><Table><thead><tr><th>机构</th><th>工单编号</th><th>反馈时间</th><th>联系人</th><th>状态</th><th>评估结果</th><th>操作</th></tr></thead><tbody>{item.workOrders.map(order => <tr key={order.id}><td>{order.institution}</td><td>{order.id}</td><td>{order.feedback?.date || '—'}</td><td>{order.feedback?.contact || '—'}</td><td><StatusTag value={order.status} /></td><td>{order.evaluation?.result || '—'}</td><td><TextAction disabled={!order.feedback} onClick={() => navigate(`/special-risks/feedback/${item.id}/evaluate?order=${order.id}`)}>查看管理报告</TextAction></td></tr>)}</tbody></Table></Section></Page>; }

function getOrder(item: SpecialRisk, orderId?: string): SpecialRiskWorkOrder { return item.workOrders.find(x => x.id === orderId) || item.workOrders[0] || { id: '新工单', institution: item.institutions[0] || '并表金融机构', issuedAt: today(), status: '待反馈' }; }

function SpecialRiskFeedbackList({ state, role, navigate, update, toast }: PageProps) { const [q, setQ] = useState({ id: '', type: '', status: '' }); const rows = state.specialRisks.flatMap(item => item.workOrders.map(order => ({ item, order }))).filter(x => (!q.id || x.order.id.includes(q.id)) && (!q.type || x.item.types.includes(q.type)) && (!q.status || x.order.status === q.status)); return <Page title="专项风险查看与反馈" breadcrumb={['专项风险管理', '专项风险查看与反馈']}><SearchPanel onSearch={() => undefined} onReset={() => setQ({ id: '', type: '', status: '' })}><Field label="工单编号"><Input value={q.id} onChange={v => setQ({ ...q, id: v })} /></Field><Field label="下发起止时间"><div className="date-range"><Input type="date" /><span>至</span><Input type="date" /></div></Field><Field label="专项风险类型"><Select value={q.type} onChange={v => setQ({ ...q, type: v })} options={specialTypes} /></Field><Field label="状态"><Select value={q.status} onChange={v => setQ({ ...q, status: v })} options={['待反馈', '已反馈', '评估中', '部分解除', '已解除', '待跟踪反馈']} /></Field></SearchPanel><Table><thead><tr><th>关联工单编号</th><th>下发日期</th><th>上次反馈时间</th><th>专项风险类型</th><th>提示名称</th><th>查看提示</th><th>状态</th><th>反馈</th><th>解除日期</th><th>报告查看</th></tr></thead><tbody>{rows.map(({ item, order }) => <tr key={order.id}><td>{order.id}</td><td>{order.issuedAt}</td><td>{order.feedback?.date || '—'}</td><td>{item.types.join('、')}</td><td>{item.name}</td><td><TextAction onClick={() => navigate(`/special-risks/manage/${item.id}`)}>查看</TextAction></td><td><StatusTag value={order.status} /></td><td>{order.status === '待反馈' || order.status === '待跟踪反馈' ? <TextAction onClick={() => navigate(`/special-risks/feedback/${item.id}?order=${order.id}`)}>{order.status === '待跟踪反馈' ? '跟踪反馈填写' : '反馈填写'}</TextAction> : '已反馈'}</td><td>{order.evaluation?.result === '解除' ? order.evaluation.date : '—'}</td><td>{order.feedback ? <TextAction onClick={() => navigate(`/special-risks/feedback/${item.id}/evaluate?order=${order.id}`)}>查看管理报告</TextAction> : '—'}</td></tr>)}</tbody></Table><Pagination total={rows.length} page={1} setPage={() => undefined} /></Page>; }

function SpecialRiskFeedback({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.specialRisks.find(x => x.id === id) || state.specialRisks[0]; const orderId = new URLSearchParams(window.location.search).get('order') || undefined; const order = getOrder(item, orderId); const [form, setForm] = useState({ contact: order.feedback?.contact || '', phone: order.feedback?.phone || '', understanding: order.feedback?.understanding || '', problems: order.feedback?.problems || '', strategy: order.feedback?.strategy || '', other: order.feedback?.other || '' }); const [files, setFiles] = useState<Attachment[]>(order.feedback?.attachments || []); const save = () => { if (!form.contact || !form.understanding || !form.problems || !form.strategy) return toast('请填写联系人、认识理解、自查问题和风险应对策略'); update(s => { const target = s.specialRisks.find(x => x.id === item.id)!; const targetOrder = target.workOrders.find(x => x.id === order.id); if (!targetOrder) return; targetOrder.feedback = { ...form, attachments: files, date: today() }; targetOrder.status = '评估中'; target.logs.push(createLog('反馈提交', `${targetOrder.institution} 提交专项风险反馈`, role)); }); toast('机构反馈已保存，状态更新为评估中'); navigate('/special-risks/feedback'); }; return <Page title="专项风险反馈填写" breadcrumb={['专项风险管理', '专项风险查看与反馈', '反馈填写']} actions={<><Button variant="secondary" onClick={() => navigate('/special-risks/feedback')}>关闭</Button><Button onClick={save}>保存</Button></>}><Section title="专项风险提示基本信息"><div className="detail-grid"><b>提示名称<span>{item.name}</span></b><b>专项风险类型<span>{item.types.join('、')}</span></b><b>下发机构<span>{order.institution}</span></b></div><div className="read-block"><b>提示背景与目的</b><p>{item.purpose}</p><b>管理措施与建议</b><p>{item.measures}</p><b>自检与反馈要求</b><p>{item.requirements}</p></div></Section><Section title="机构反馈"><div className="form-grid"><Field label="反馈机构"><Input value={order.institution} disabled /></Field><Field label="联系人" required><Input value={form.contact} onChange={v => setForm({ ...form, contact: v })} /></Field><Field label="联系电话"><Input value={form.phone} onChange={v => setForm({ ...form, phone: v })} /></Field><Field label="对专项风险提示的认识与理解" required><Textarea value={form.understanding} onChange={v => setForm({ ...form, understanding: v })} /></Field><Field label="自查发现的问题与风险点" required><Textarea value={form.problems} onChange={v => setForm({ ...form, problems: v })} /></Field><Field label="未来风险预防与应对策略" required><Textarea value={form.strategy} onChange={v => setForm({ ...form, strategy: v })} /></Field><Field label="其他总结反馈"><Textarea value={form.other} onChange={v => setForm({ ...form, other: v })} /></Field></div></Section><Section title="附件"><FileUploader files={files} onChange={setFiles} /></Section></Page>; }

function SpecialRiskEvaluate({ state, role, navigate, update, toast }: PageProps) { const id = window.location.pathname.split('/')[3]; const item = state.specialRisks.find(x => x.id === id) || state.specialRisks[0]; const orderId = new URLSearchParams(window.location.search).get('order') || undefined; const order = getOrder(item, orderId); const [form, setForm] = useState({ result: order.evaluation?.result || '部分解除', department: order.evaluation?.department || '金融机构管理部', summary: order.evaluation?.summary || '' }); const [files, setFiles] = useState<Attachment[]>(order.evaluation?.attachments || []); const save = (draft: boolean) => { if (!draft && !form.summary) return toast('请填写分析及总结'); update(s => { const target = s.specialRisks.find(x => x.id === item.id)!; const targetOrder = target.workOrders.find(x => x.id === order.id); if (!targetOrder) return; targetOrder.evaluation = { ...form, result: form.result as '解除' | '部分解除' | '驳回', date: today(), attachments: files }; targetOrder.status = form.result === '解除' ? '已解除' : form.result === '部分解除' ? '部分解除' : '待跟踪反馈'; target.logs.push(createLog(draft ? '保存评估草稿' : '提交评估', `${targetOrder.institution} 评估结果：${form.result}`, role)); }); toast(draft ? '评估草稿已保存' : '评估结果已保存并同步机构工单状态'); if (!draft) navigate('/special-risks/manage'); }; return <Page title="专项风险反馈评估" breadcrumb={['专项风险管理', '专项风险查看与反馈', '反馈评估']} actions={<><Button variant="secondary" onClick={() => navigate('/special-risks/manage')}>关闭</Button><Button variant="secondary" onClick={() => save(true)}>保存草稿</Button><Button onClick={() => save(false)}>保存</Button></>}><Section title="提示基本信息"><div className="detail-grid"><b>提示名称<span>{item.name}</span></b><b>类型<span>{item.types.join('、')}</span></b><b>反馈机构<span>{order.institution}</span></b></div></Section><Section title="机构反馈信息"><div className="read-block"><b>联系人及电话</b><p>{order.feedback?.contact || '—'} {order.feedback?.phone || ''}</p><b>认识与理解</b><p>{order.feedback?.understanding || '—'}</p><b>自查问题与风险点</b><p>{order.feedback?.problems || '—'}</p><b>未来风险预防与应对策略</b><p>{order.feedback?.strategy || '—'}</p><b>其他总结反馈</b><p>{order.feedback?.other || '—'}</p></div></Section><Section title="评估区"><div className="form-grid"><Field label="评估结果" required><Select value={form.result} onChange={v => setForm({ ...form, result: v })} options={['解除', '部分解除', '驳回']} /></Field><Field label="评估部门" required><Select value={form.department} onChange={v => setForm({ ...form, department: v })} options={departments} /></Field><Field label="分析及总结" span={2}><Textarea value={form.summary} onChange={v => setForm({ ...form, summary: v })} /></Field></div></Section><Section title="反馈附件"><FileUploader files={files} onChange={setFiles} /></Section></Page>; }
